# Patch observational diagnostics and BOTH evaluator strings; preserve TRAIN_CONFIG.
SOURCES.update({'v21_diagnostics.py': '"""Label-free runtime traces; frame annotations are read only by post-hoc analysis.\n\nNo tensors here change a forward, loss, gradient, optimizer or sample selection.\nDiagnostic reruns happen after the timed inference call with the model in eval mode.\n"""\n\nimport csv\nimport json\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\n\n\ndef append_json(path, row):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    with path.open("a", encoding="utf-8") as stream:\n        stream.write(json.dumps(row, ensure_ascii=False, allow_nan=False) + "\\n")\n\n\ndef tensor_summary(value):\n    value = value.detach()\n    if not value.numel() or not bool(torch.isfinite(value).all()):\n        raise ValueError("Empty/nonfinite tensor in observed data flow")\n    x = value.double()\n    return {"shape": list(value.shape), "dtype": str(value.dtype),\n            "min": float(x.min()), "max": float(x.max()),\n            "rms": float(x.square().mean().sqrt())}\n\n\nclass StageTrace:\n    """Temporary hooks on real modules; output statistics include padded tokens."""\n\n    def __init__(self, base, geometry=None):\n        modules = dict(base.named_children())\n        names = [n for n in modules if n in {"temporal", "linear", "classifier", "mlp1", "mlp2",\n                                            "text_prompt_embeddings"} or\n                 n.startswith("gc") and n[2:].isdigit()]\n        self.modules = {n: modules[n] for n in names}\n        if hasattr(base, "clipmodel") and hasattr(base.clipmodel, "transformer"):\n            self.modules["clip_text_transformer"] = base.clipmodel.transformer\n        if geometry is not None:\n            self.modules.update(visual_projection=geometry.visual, text_projection=geometry.text)\n        self.rows, self.handles, self.adapter = [], [], None\n        self.active_stage = "input"\n\n    def __enter__(self):\n        for name, module in self.modules.items():\n            def before(module, args, name=name):\n                self.active_stage = name\n\n            def after(module, args, value, name=name):\n                tensors = [value] if isinstance(value, torch.Tensor) else list(value)\n                info = [tensor_summary(x) for x in tensors if isinstance(x, torch.Tensor)]\n                self.rows.append({"stage": name, "outputs": info})\n                if name == "linear":\n                    self.adapter = value.detach()\n\n            self.handles.extend((module.register_forward_pre_hook(before),\n                                 module.register_forward_hook(after)))\n        return self\n\n    def __exit__(self, *_):\n        for handle in self.handles:\n            handle.remove()\n\n\ndef check_batch(visual, lengths, targets, c, a, aux, ids, samples):\n    """Checks every training microbatch, including identity/temporal sampling receipts."""\n    sizes = torch.as_tensor(lengths, device=visual.device)\n    b, width, dim = visual.shape\n    if (b != len(ids) or dim != 512 or len(samples) != b or sizes.shape != (b,)\n            or bool(((sizes < 1) | (sizes > width)).any())):\n        raise ValueError(f"Invalid train sample/length/grid: {ids}")\n    if c.shape != (b, width, 1) or a.shape[:2] != (b, width) or targets.shape != (b, a.shape[-1]):\n        raise ValueError(f"Train logits/targets do not match input grid: {ids}")\n    if (not bool(((targets == 0) | (targets == 1)).all()) or\n            bool((targets.sum(-1) < 1).any()) or\n            bool(((targets[:, 0] > 0) & (targets[:, 1:].sum(-1) > 0)).any())):\n        raise ValueError(f"Invalid encoded normal/anomaly targets: {ids}")\n    valid = torch.arange(width, device=visual.device)[None] < sizes[:, None]\n    if not torch.equal(valid, aux["valid"]):\n        raise ValueError("Training padding/valid mask mismatch")\n    stages = {"sampled_input": tensor_summary(visual), "adapter": tensor_summary(aux["adapter"]),\n              "classification_logits": tensor_summary(c), "alignment_logits": tensor_summary(a)}\n    if bool((visual[~valid] != 0).any()):\n        raise ValueError("Nonzero training padding")\n    rows = []\n    for i, (video_id, sample) in enumerate(zip(ids, samples, strict=True)):\n        n = int(sizes[i])\n        indices = np.asarray(sample["selected_indices"])\n        if (len(indices) != n or indices.min() < 0 or indices.max() >= sample["source_steps"]\n                or bool((np.diff(indices) <= 0).any())):\n            raise ValueError(f"Invalid temporal sample indices: {video_id}")\n        z = c[i, :n, 0].detach().float()\n        p = z.sigmoid()\n        abnormal = bool(targets[i, 0] == 0)\n        rows.append({"video_id": video_id, **sample, "valid_steps": n,\n                     "abnormal_video_label": abnormal,\n                     "classification_logit_min": float(z.min()),\n                     "classification_logit_max": float(z.max()),\n                     "classification_probability_mean": float(p.mean()),\n                     "rounded_zero_count": int((p == 0).sum()),\n                     "rounded_one_count": int((p == 1).sum()),\n                     "video_label_opposite_rounded_count": int((p == (0 if abnormal else 1)).sum()),\n                     "adapter_norm_mean": float(aux["adapter"][i, :n].detach().norm(dim=-1).mean())})\n    return {"stage_checks": stages, "videos": rows}\n\n\ndef summarize_training(output, health, expected_ids=None):\n    """Actual sample exposure, not assumed coverage of an event without frame labels."""\n    output = Path(output)\n    coverage, rows_checked, wrong_rounding = {}, 0, 0\n    path = output / "training_flow.jsonl"\n    with path.open(encoding="utf-8") as stream:\n        for line in stream:\n            row = json.loads(line)\n            if row["status"] != "ok":\n                continue\n            rows_checked += 1\n            for video in row["videos"]:\n                key = video["video_id"]\n                n = video["source_steps"]\n                if key not in coverage:\n                    coverage[key] = {"seen": np.zeros(n, dtype=bool), "exposures": 0,\n                                     "opposite_rounded_tokens": 0, "valid_tokens": 0}\n                entry = coverage[key]\n                if len(entry["seen"]) != n:\n                    raise ValueError(f"Source feature length changed during training: {key}")\n                entry["seen"][video["selected_indices"]] = True\n                entry["exposures"] += 1\n                entry["opposite_rounded_tokens"] += video["video_label_opposite_rounded_count"]\n                entry["valid_tokens"] += video["valid_steps"]\n                wrong_rounding += video["video_label_opposite_rounded_count"]\n    rows = [{"video_id": key, "source_steps": len(value["seen"]),\n             "observed_forward_exposures": value["exposures"],\n             "unique_sampled_steps": int(value["seen"].sum()),\n             "sampled_step_coverage": float(value["seen"].mean()),\n             "valid_tokens_observed": value["valid_tokens"],\n             "video_label_opposite_rounded_tokens": value["opposite_rounded_tokens"]} for key,value in coverage.items()]\n    if rows:\n        with (output / "training_sample_coverage.csv").open("w", newline="", encoding="utf-8") as stream:\n            writer = csv.DictWriter(stream, fieldnames=list(rows[0]))\n            writer.writeheader()\n            writer.writerows(rows)\n    alerts = []\n    for batch in health:\n        for micro in batch["microbatches"]:\n            for video_id, entry in zip(micro["video_ids"], micro["temporal"], strict=True):\n                if entry.get("wrong_saturated_pool"):\n                    alerts.append({"epoch": batch["epoch"], "batch": batch["batch"], "video_id": video_id,\n                                   "stage": "native_sigmoid_MIL_BCE", "evidence": "pooled probability rounded to wrong endpoint",\n                                   "bce_gradient_at_raw_c_norm": entry.get("bce_gradient_at_raw_c_norm"),\n                                   "causal_origin": "unresolved; compare LR-only pilot before any loss change"})\n    summary = {"microbatch_checks": rows_checked, "unique_training_videos_observed": len(rows),\n               "eligible_videos_not_observed": sorted(set(expected_ids or []) - set(coverage)),\n               "video_label_opposite_rounded_tokens": wrong_rounding, "alerts": alerts,\n               "rounding_count_scope": "opposite video-level target; not per-frame error labels for abnormal videos",\n               "frame_labels_used": False, "diagnostic_changes_training": False,\n               "coverage_scope": "observed training forwards, including AMP retries if any; not event coverage",\n               "internal_stage_scope": "first configured health batches; input/adapter/logits/masks checked each microbatch",\n               "training_sample_coverage_file": "training_sample_coverage.csv"}\n    (output / "training_diagnosis.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")\n    return summary\n\n\nclass EvaluationTrace:\n    def __init__(self, output, dataset, variant):\n        self.output = Path(output)\n        self.output.mkdir(parents=True, exist_ok=True)\n        self.dataset, self.variant = dataset, variant\n        self.ids, self.parts, self.offsets, self.prompts = [], [], [0], None\n\n    @torch.no_grad()\n    def observe(self, video_id, base, dispatch, visual, lengths, mask, measured, steps, geometry=None, prompts=None,\n                expected_features=None):\n        trace = StageTrace(base, geometry)\n        try:\n            if base.training:\n                raise ValueError("Diagnostic replay requires model.eval()")\n            if visual.ndim != 3:\n                raise ValueError("Evaluator input must be [blocks,width,features]")\n            width = visual.shape[1]\n            capacity = visual.shape[0]*width\n            if not 0 < steps <= capacity:\n                raise ValueError(f"Original feature steps exceed evaluator tensor capacity: {steps}/{capacity}")\n            # Export always trims the original feature grid. Native model lengths\n            # are a separate argument; XD\'s upstream implementation may include\n            # padded context. Never replace those arguments or change its forward.\n            valid = (torch.arange(capacity, device=visual.device) < steps).reshape(visual.shape[:2])\n            export_lengths = valid.sum(-1)\n            sizes = None if lengths is None else torch.as_tensor(lengths, device=visual.device)\n            trace.active_stage = "native_context_metadata"\n            if sizes is not None and (not bool(torch.isfinite(sizes).all()) or bool((sizes < 0).any())):\n                raise ValueError("Nonfinite or negative native evaluator lengths")\n            if mask is not None and (not bool(torch.isfinite(mask).all()) or\n                                     not bool(((mask == 0) | (mask == 1)).all())):\n                raise ValueError("Evaluator mask is nonfinite or not binary")\n            length_contract = (sizes is not None and sizes.shape == (len(visual),)\n                               and bool(torch.isfinite(sizes).all())\n                               and bool(((sizes >= 0) & (sizes <= width)).all())\n                               and torch.equal(sizes, export_lengths.to(sizes)))\n            padding_count = int((visual[~valid] != 0).sum())\n            mask_contract = mask is None or (mask.shape == valid.shape and torch.equal(mask.bool(), ~valid))\n            if self.dataset != "xd":\n                if not length_contract:\n                    raise ValueError("Evaluator valid lengths do not match original feature steps")\n                if not mask_contract:\n                    raise ValueError("Evaluator padding mask is inconsistent with lengths")\n                if padding_count:\n                    raise ValueError("Nonzero evaluation padding")\n            elif expected_features is None:\n                raise ValueError("XD trace requires original features to verify exported token identity")\n            trace.active_stage = "input_feature_identity"\n            if expected_features is not None:\n                original = np.asarray(expected_features)\n                if original.shape != (steps, visual.shape[-1]) or not np.isfinite(original).all():\n                    raise ValueError("Original feature shape/finite values differ from evaluator inventory")\n                expected = torch.as_tensor(np.array(original, copy=True), device=visual.device, dtype=visual.dtype)\n                if not torch.equal(visual.reshape(-1, visual.shape[-1])[:steps], expected):\n                    raise ValueError("Evaluator input token values/order differ from original features")\n            input_info = tensor_summary(visual)\n            trace.active_stage = "native_forward_replay"\n            with trace:\n                replayed = dispatch()\n            trace.active_stage = "raw_forward_outputs"\n            if len(replayed) != len(measured):\n                raise ValueError("Diagnostic/timed result structure mismatch")\n            for name, left, right in zip(("text_encoder_output", "classification_logits", "alignment_logits"),\n                                         measured, replayed, strict=True):\n                trace.active_stage = name\n                tensor_summary(left)\n                tensor_summary(right)\n                if left.shape != right.shape or not torch.allclose(left, right, rtol=1e-5, atol=1e-6):\n                    raise ValueError("Diagnostic replay differs from timed output")\n            # Preserve the actual timed logits. Hooked replay may use a different\n            # Transformer kernel with tiny floating-point differences.\n            _, c, a = measured\n            trace.active_stage = "output_grid_and_prompt_order"\n            if c.shape != (*visual.shape[:2], 1) or a.shape[:2] != visual.shape[:2] or a.shape[-1] < 2:\n                raise ValueError("Evaluation raw logits do not match block grid")\n            if prompts is None or len(prompts) != a.shape[-1] or str(prompts[0]).casefold() != "normal":\n                raise ValueError("Evaluation prompt order must match logits with normal at index 0")\n            if self.prompts is not None and list(prompts) != self.prompts:\n                raise ValueError("Prompt order changed between evaluation videos")\n            self.prompts = list(prompts)\n            if trace.adapter is None or trace.adapter.shape[:2] != visual.shape[:2]:\n                raise ValueError("Missing temporal adapter output on evaluation grid")\n            z = c.reshape(-1)[:steps]\n            align = a.reshape(-1, a.shape[-1])[:steps]\n            trace.active_stage = "probability_conversion"\n            scores = torch.stack((z.sigmoid(), 1 - align.softmax(-1)[:, 0]), -1)\n            odds = torch.logsumexp(align.double()[:, 1:], -1) - align.double()[:, 0]\n            values = {"classification_logits": z, "alignment_logits": align,\n                      "alignment_log_odds": odds, "scores": scores,\n                      "adapter_norm": trace.adapter.norm(dim=-1).reshape(-1)[:steps],\n                      "feature_norm": visual.norm(dim=-1).reshape(-1)[:steps],\n                      "block_index": torch.arange(steps, device=z.device) // width}\n            self.parts.append({k: v.cpu().numpy() for k, v in values.items()})\n            self.ids.append(str(video_id))\n            self.offsets.append(self.offsets[-1] + steps)\n            append_json(self.output / "evaluation_flow.jsonl", {\n                "video_id": str(video_id), "status": "ok", "input": input_info,\n                "valid_lengths": export_lengths.cpu().tolist(), "export_steps": steps,\n                "model_lengths": None if sizes is None else sizes.cpu().tolist(),\n                "model_lengths_shape": None if sizes is None else list(sizes.shape),\n                "model_lengths_match_export": bool(length_contract),\n                "padding_mask_supplied": mask is not None, "mask_matches_export": bool(mask_contract),\n                "model_mask_shape": None if mask is None else list(mask.shape),\n                "nonzero_context_values_after_export": padding_count,\n                "input_matches_original_features": expected_features is not None,\n                "native_arguments_modified": False,\n                "length_scope": "native model context and exported feature grid are separate; differences are observations",\n                "normal_class_index": 0, "prompt_order": self.prompts,\n                "stages": trace.rows, "classification_logits": tensor_summary(z),\n                "alignment_logits": tensor_summary(align), "replay_matches_timed_output": True,\n                "timing_scope": "diagnostic replay excluded from latency.measure"})\n        except Exception as exc:\n            append_json(self.output / "evaluation_flow.jsonl", {\n                "video_id": str(video_id), "status": "failed", "stage": trace.active_stage,\n                "original_steps": int(steps), "input_shape": list(visual.shape),\n                "model_lengths_repr": repr(lengths),\n                "completed_stages": trace.rows, "error": f"{type(exc).__name__}: {exc}"})\n            raise\n\n    def finish(self):\n        if len(self.ids) != len(set(self.ids)) or not self.parts:\n            raise ValueError("Empty or duplicated evaluation trace")\n        np.savez_compressed(self.output / "diagnostic_tensors.npz",\n                            video_id=np.asarray(self.ids), snippet_offsets=np.asarray(self.offsets),\n                            **{k: np.concatenate([part[k] for part in self.parts]) for k in self.parts[0]})\n        (self.output / "trace_contract.json").write_text(json.dumps({\n            "schema": "v21_flow_error_audit_v1", "dataset": self.dataset, "variant": self.variant,\n            "video_count": len(self.ids), "snippet_count": self.offsets[-1],\n            "prompt_order": self.prompts, "normal_class_index": 0,\n            "test_labels_used": False, "changes_predictions": False,\n            "tolerances": {"replay_rtol": 1e-5, "replay_atol": 1e-6},\n            "limitation": "shape/finite checks cannot establish semantic feature quality or causal blame",\n        }, indent=2), encoding="utf-8")\n', 'v21_error_analysis.py': '"""Post-hoc benchmark failures. Never imported by the training subprocess.\n\nThe fixed 0.5 threshold is an uncalibrated diagnostic, not selected on the test.\nRanking metrics and raw-vs-rounded scores accompany it. No automatic causal claim.\n"""\n\nimport csv\nimport hashlib\nimport json\nfrom collections import defaultdict\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom sklearn.metrics import average_precision_score, roc_auc_score\n\n\ndef write_csv(path, rows):\n    if not rows:\n        Path(path).write_text("dataset,variant,branch,video_id\\n", encoding="utf-8")\n        return\n    with Path(path).open("w", newline="", encoding="utf-8") as stream:\n        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))\n        writer.writeheader()\n        writer.writerows(rows)\n\n\ndef intervals(mask):\n    edges = np.diff(np.r_[False, np.asarray(mask, dtype=bool), False].astype(np.int8))\n    return list(zip(np.flatnonzero(edges == 1), np.flatnonzero(edges == -1), strict=True))\n\n\ndef auc(y, score):\n    return float(roc_auc_score(y, score)) if len(np.unique(y)) == 2 else None\n\n\ndef load_prediction(path):\n    report = json.loads(Path(path).read_text(encoding="utf-8"))\n    with np.load(Path(path).with_name("predictions.npz"), allow_pickle=False) as data:\n        arrays = dict(data)\n    id_key = "video_id" if "video_id" in arrays else "official_path"\n    ids = arrays[id_key].astype(str)\n    offsets = arrays["snippet_offsets"]\n    scores, gt = arrays["scores"], arrays["frame_gt"].reshape(-1)\n    fpf = report["frames_per_feature"]\n    if (type(fpf) is not int or fpf < 1 or len(ids) != len(set(ids)) or\n            len(arrays["video_label"]) != len(ids) or offsets.shape != (len(ids) + 1,) or\n            offsets.dtype.kind not in "iu" or offsets[0] != 0 or\n            bool((np.diff(offsets) <= 0).any()) or offsets[-1] != len(scores) or\n            scores.shape != (offsets[-1], 2) or\n            not np.isfinite(scores).all() or bool(((scores < 0) | (scores > 1)).any()) or\n            len(gt) != offsets[-1] * fpf or not np.isin(gt, [0, 1]).all()):\n        raise ValueError("Invalid saved ID/offset/score/frame-GT grid")\n    arrays["ids"] = ids\n    return report, arrays\n\n\ndef probability_replay(trace, directory):\n    """Check saved device probabilities against an independent FP64 CPU reference.\n\n    CPU and CUDA reductions are not bitwise interchangeable. Use a disclosed\n    absolute budget in probability space based on the stored logit precision\n    and class count. Never replace the probabilities used for benchmark metrics.\n    """\n    z = torch.from_numpy(trace["classification_logits"])\n    align = torch.from_numpy(trace["alignment_logits"])\n    if z.ndim != 1 or align.ndim != 2 or align.shape[1] < 2:\n        raise ValueError("Invalid raw diagnostic logit shapes")\n    if any(trace[key].dtype not in (np.float32, np.float64) for key in ("classification_logits", "alignment_logits")):\n        raise ValueError("Replay requires stored FP32/FP64 logits")\n    eps = [np.finfo(trace[key].dtype).eps for key in ("classification_logits", "alignment_logits")]\n    tolerances = [float(max(8*eps[0], 64*np.finfo(np.float64).eps)),\n                  float(max((align.shape[1]+4)*eps[1], 64*np.finfo(np.float64).eps))]\n    reference = torch.stack((z.double().sigmoid(), 1-align.double().softmax(-1)[:, 0]), -1).numpy()\n    error = np.abs(reference-trace["scores"])\n    rows, examples = [], []\n    for column, branch in enumerate(("classification", "alignment")):\n        bad = np.flatnonzero(error[:, column] > tolerances[column])\n        rows.append({"branch": branch, "absolute_tolerance": tolerances[column],\n                     "max_absolute_error": float(error[:, column].max()),\n                     "p99_absolute_error": float(np.quantile(error[:, column], .99)),\n                     "mismatch_count": len(bad), "stored_logit_dtype": str((z, align)[column].dtype)})\n        for token in sorted(bad, key=lambda i: error[i, column], reverse=True)[:10]:\n            video = int(np.searchsorted(trace["snippet_offsets"], token, side="right")-1)\n            examples.append({"video_id": str(trace["video_id"][video]), "branch": branch,\n                             "snippet_index": int(token-trace["snippet_offsets"][video]),\n                             "recorded_probability": float(trace["scores"][token, column]),\n                             "reference_probability_fp64": float(reference[token, column]),\n                             "absolute_error": float(error[token, column]),\n                             "raw_logits": (float(z[token]) if column == 0 else align[token].tolist())})\n    receipt = {"schema": "v21_probability_replay_v2", "reference": "CPU float64 from stored raw logits",\n               "policy": "absolute probability error: C 8*eps; A (classes+4)*eps; floor 64*eps64",\n               "status": "failed" if examples else "passed", "branches": rows, "examples": examples,\n               "benchmark_scores_modified": False,\n               "scope": "cross-backend numerical check; ID/offset/export/GT/metric checks are separate"}\n    (Path(directory) / "probability_replay.json").write_text(\n        json.dumps(receipt, indent=2, allow_nan=False), encoding="utf-8")\n    if examples:\n        worst = examples[0]\n        raise ValueError(f"Saved raw logits do not reproduce trace probabilities beyond dtype budget: "\n                         f"{worst[\'video_id\']}/{worst[\'branch\']}/snippet={worst[\'snippet_index\']}; "\n                         f"abs_error={worst[\'absolute_error\']:.9g}; see probability_replay.json")\n    return receipt\n\n\ndef load_trace(path, arrays):\n    directory = Path(path).parent / "diagnostics"\n    with np.load(directory / "diagnostic_tensors.npz", allow_pickle=False) as data:\n        trace = dict(data)\n    trace_ids, offsets = trace["video_id"].astype(str), trace["snippet_offsets"]\n    if len(trace_ids) != len(set(trace_ids)) or set(trace_ids) != set(arrays["ids"]):\n        raise ValueError("Trace/evaluator video identities differ")\n    if (offsets.shape != (len(trace_ids) + 1,) or offsets[0] != 0 or\n            offsets.dtype.kind not in "iu" or bool((np.diff(offsets) <= 0).any())):\n        raise ValueError("Invalid trace offsets")\n    keys = ("classification_logits", "alignment_logits", "alignment_log_odds", "scores",\n            "adapter_norm", "feature_norm", "block_index")\n    for key in keys:\n        if len(trace[key]) != offsets[-1] or not np.isfinite(trace[key]).all():\n            raise ValueError(f"Invalid diagnostic tensor: {key}")\n    if trace["scores"].shape != arrays["scores"].shape:\n        raise ValueError("Diagnostic score columns differ from evaluator")\n    align = torch.from_numpy(trace["alignment_logits"])\n    probability_replay(trace, directory)\n    odds = (torch.logsumexp(align.double()[:, 1:], -1)-align.double()[:, 0]).numpy()\n    if not np.allclose(odds, trace["alignment_log_odds"], rtol=1e-10, atol=1e-8):\n        raise ValueError("Saved alignment log odds differ from raw alignment logits")\n    index = {video_id: i for i, video_id in enumerate(trace_ids)}\n    aligned = {key: [] for key in keys}\n    for i, video_id in enumerate(arrays["ids"]):\n        j = index[video_id]\n        start, end = offsets[j:j+2]\n        left, right = arrays["snippet_offsets"][i:i+2]\n        if end - start != right - left:\n            raise ValueError(f"Trace/evaluator per-video lengths differ: {video_id}")\n        for key in keys:\n            aligned[key].append(trace[key][start:end])\n    aligned = {key: np.concatenate(value) for key, value in aligned.items()}\n    if not np.allclose(aligned["scores"], arrays["scores"], rtol=1e-6, atol=1e-7):\n        raise ValueError("Raw-logit score conversion/trim differs from benchmark export")\n    return aligned\n\n\ndef analyze_benchmark(dataset, paths, output, require_trace=True):\n    """Compare every treatment to V0 with the same per-video frame grid and hashes."""\n    output = Path(output)\n    output.mkdir(parents=True, exist_ok=True)\n    if "v0" not in paths or len(paths) < 2:\n        raise ValueError("Error analysis requires same-run V0 and a treatment")\n    all_rows, errors, events, evidence = [], [], [], []\n    sources, signature, feature_reference = {}, None, None\n    for variant, path in paths.items():\n        report, arrays = load_prediction(path)\n        sources[variant] = {"run_json": str(path), "prediction_sha256": hashlib.sha256(\n            Path(path).with_name("predictions.npz").read_bytes()).hexdigest()}\n        current_signature = (arrays["ids"].tolist(), arrays["snippet_offsets"].tolist(),\n                             arrays["video_label"].tolist(), arrays["score_columns"].tolist(),\n                             report["frames_per_feature"], report["visual_block_length"],\n                             hashlib.sha256(arrays["frame_gt"].tobytes()).hexdigest())\n        if signature is not None and signature != current_signature:\n            raise ValueError("V0/treatment sample/label/score/frame grids differ")\n        signature = current_signature\n        videos = {str(v.get("id", v.get("official_path"))): v for v in report["videos"]}\n        if len(videos) != len(arrays["ids"]) or set(videos) != set(arrays["ids"]):\n            raise ValueError("Input metadata/evaluator video identities differ")\n        feature_hashes = {key: value.get("feature_sha256") for key, value in videos.items()}\n        if any(not value for value in feature_hashes.values()):\n            raise ValueError("Missing per-video input feature provenance")\n        if feature_reference is not None and feature_hashes != feature_reference:\n            raise ValueError("V0/treatment per-video input feature hashes differ")\n        feature_reference = feature_hashes\n        trace_path = Path(path).parent / "diagnostics/diagnostic_tensors.npz"\n        trace = load_trace(path, arrays) if require_trace or trace_path.exists() else None\n        fpf, width = report["frames_per_feature"], report["visual_block_length"]\n        replay_metrics = {}\n        for column, branch in enumerate(arrays["score_columns"].astype(str)):\n            y, score = arrays["frame_gt"], np.repeat(arrays["scores"][:, column], fpf)\n            replay_metrics[branch] = {"roc_auc": auc(y, score),\n                                      "ap": float(average_precision_score(y, score))}\n            saved = report["metrics"][branch]\n            if "ano_auc" in saved:\n                abnormal = np.array([str(label).casefold() not in {"a", "normal"}\n                                     for label in arrays["video_label"]])\n                mask = np.repeat(abnormal, np.diff(arrays["snippet_offsets"])*fpf)\n                replay_metrics[branch]["ano_auc"] = auc(y[mask], score[mask])\n            for metric, value in replay_metrics[branch].items():\n                saved_key = "frame_ap" if metric == "ap" and "frame_ap" in saved else metric\n                if saved_key in saved and (value is None or abs(value - saved[saved_key]) > 1e-9):\n                    raise ValueError(f"Saved benchmark metric cannot be replayed: {variant}/{branch}/{metric}")\n            if trace is not None:\n                raw = trace["classification_logits"] if column == 0 else trace["alignment_log_odds"]\n                raw = np.repeat(raw, fpf)\n                replay_metrics[branch].update(raw_roc_auc=auc(y, raw),\n                                             raw_ap=float(average_precision_score(y, raw)))\n        sources[variant]["replayed_metrics"] = replay_metrics\n        for i, video_id in enumerate(arrays["ids"]):\n            start, end = (int(x) for x in arrays["snippet_offsets"][i:i+2])\n            label = str(arrays["video_label"][i])\n            y = arrays["frame_gt"][start*fpf:end*fpf].astype(bool)\n            normal = label.casefold() in {"a", "normal"}\n            if normal and bool(y.any()):\n                raise ValueError(f"Normal video contains event frame GT: {video_id}")\n            if videos[video_id]["steps"] != end - start:\n                raise ValueError(f"Input feature/benchmark step count differs: {video_id}")\n            if trace is not None and not np.array_equal(trace["block_index"][start:end], np.arange(end-start)//width):\n                raise ValueError(f"Trace block boundaries differ from evaluator grid: {video_id}")\n            gt_events = intervals(y)\n            for col, branch in enumerate(arrays["score_columns"].astype(str)):\n                snippet_score = arrays["scores"][start:end, col]\n                score = np.repeat(snippet_score, fpf)\n                predicted = score >= .5\n                fp, fn = predicted & ~y, ~predicted & y\n                raw = (trace["classification_logits"] if col == 0 else trace["alignment_log_odds"])[start:end] if trace else None\n                raw_frame = np.repeat(raw, fpf) if raw is not None else None\n                rank_auc = auc(y, score)\n                raw_auc = auc(y, raw_frame) if raw_frame is not None else None\n                stage = ("probability_rounding" if raw_auc is not None and rank_auc is not None and raw_auc - rank_auc > 1e-6\n                         else "raw_output_ranking" if raw_auc is not None and raw_auc < .5\n                         else "probability_output_ranking_no_raw_trace" if raw is None and rank_auc is not None and rank_auc < .5\n                         else "fixed_threshold_decision" if (fp.any() or fn.any())\n                         else "no_error_at_fixed_threshold")\n                raw_diagnostic = "available" if trace is not None else "unavailable_historical_output"\n                k = 1 + (end-start) // 16\n                top = np.argsort(-snippet_score, kind="stable")[:k]\n                token_event_fraction = y.reshape(-1, fpf).mean(-1)\n                norm = trace["adapter_norm"][start:end] if trace else None\n                row = {"dataset": dataset, "variant": variant, "branch": branch, "video_id": video_id,\n                       "label": label, "feature_sha256": feature_hashes[video_id],\n                       "steps": end-start, "frames": len(y), "block_count": (end-start+width-1)//width,\n                       "padding_fraction": 1-(end-start)/(((end-start+width-1)//width)*width),\n                       "event_frames": int(y.sum()), "event_fraction": float(y.mean()),\n                       "event_count": len(gt_events), "shortest_event_frames": min((b-a for a,b in gt_events), default=0),\n                       "within_video_auc": rank_auc, "raw_within_video_auc": raw_auc,\n                       "frame_ap": float(average_precision_score(y, score)) if y.any() else None,\n                       "tp_frames": int((predicted & y).sum()), "fp_frames": int(fp.sum()),\n                       "fn_frames": int(fn.sum()), "tn_frames": int((~predicted & ~y).sum()),\n                       "event_recall_at_0_5": float(predicted[y].mean()) if y.any() else None,\n                       "background_fpr_at_0_5": float(predicted[~y].mean()) if (~y).any() else None,\n                       "event_background_score_gap": float(score[y].mean()-score[~y].mean()) if y.any() and (~y).any() else None,\n                       "score_std": float(score.std()), "exact_zero_one_fraction": float(((score==0)|(score==1)).mean()),\n                       "diagnostic_topk": k, "topk_event_fraction": float(token_event_fraction[top].mean()),\n                       "adapter_norm_mean": float(norm.mean()) if norm is not None else None,\n                       "observed_stage": stage, "raw_trace": raw_diagnostic,\n                       "causal_origin": "unresolved; upstream stages may cause the observed output error"}\n                all_rows.append(row)\n                if fp.any() or fn.any() or (rank_auc is not None and rank_auc < .5):\n                    evidence.append({"dataset": dataset, "variant": variant, "branch": branch,\n                                     "video_id": video_id, "observed_stage": stage,\n                                     "evidence_level": "observed score behavior; causal origin unresolved",\n                                     "probability_auc": rank_auc, "raw_auc": raw_auc,\n                                     "fp_frames_at_0_5": int(fp.sum()), "fn_frames_at_0_5": int(fn.sum())})\n                for kind, mask in (("FP", fp), ("FN", fn)):\n                    for lo, hi in intervals(mask):\n                        left, right = lo//fpf, (hi-1)//fpf+1\n                        errors.append({"dataset": dataset, "variant": variant, "branch": branch,\n                                       "video_id": video_id, "label": label, "error": kind,\n                                       "start_frame_0based": int(lo), "end_frame_exclusive": int(hi),\n                                       "frames": int(hi-lo), "start_snippet": int(left), "end_snippet_exclusive": int(right),\n                                       "start_block": int(left//width), "end_block": int((right-1)//width),\n                                       "score_mean": float(score[lo:hi].mean()),\n                                       "raw_score_mean": float(raw_frame[lo:hi].mean()) if raw_frame is not None else None,\n                                       "adapter_norm_mean": float(norm[left:right].mean()) if norm is not None else None,\n                                       "observed_stage": stage})\n                for lo, hi in gt_events:\n                    events.append({"dataset": dataset, "variant": variant, "branch": branch,\n                                   "video_id": video_id, "label": label, "start_frame_0based": int(lo),\n                                   "end_frame_exclusive": int(hi), "frames": int(hi-lo),\n                                   "recall_at_0_5": float(predicted[lo:hi].mean()),\n                                   "fully_missed_at_0_5": not bool(predicted[lo:hi].any()),\n                                   "score_mean": float(score[lo:hi].mean()),\n                                   "crosses_block_boundary": lo//(width*fpf) != (hi-1)//(width*fpf)})\n    indexed = {(r["variant"], r["branch"], r["video_id"]): r for r in all_rows}\n    paired = []\n    for row in all_rows:\n        if row["variant"] == "v0":\n            continue\n        ref = indexed["v0", row["branch"], row["video_id"]]\n        paired.append({"dataset": dataset, "variant": row["variant"], "branch": row["branch"],\n                       "video_id": row["video_id"], "label": row["label"],\n                       "v0_within_video_auc": ref["within_video_auc"], "treatment_within_video_auc": row["within_video_auc"],\n                       "auc_delta_pp": 100*(row["within_video_auc"]-ref["within_video_auc"]) if row["within_video_auc"] is not None else None,\n                       "fp_frame_delta_at_0_5": row["fp_frames"]-ref["fp_frames"],\n                       "fn_frame_delta_at_0_5": row["fn_frames"]-ref["fn_frames"],\n                       "observed_stage": row["observed_stage"]})\n    grouped = defaultdict(list)\n    for row in all_rows:\n        attributes = {"label": row["label"], "length": "multiple_blocks" if row["block_count"] > 1 else "one_block",\n                      "event_density": "no_event" if row["event_fraction"] == 0 else "sparse_le_10pct" if row["event_fraction"] <= .1 else "dense_gt_10pct",\n                      "short_event": "no_event" if row["event_count"] == 0 else "le_64_frames" if row["shortest_event_frames"] <= 64 else "gt_64_frames",\n                      "rounding": "ge_95pct_exact_0_or_1" if row["exact_zero_one_fraction"] >= .95 else "lt_95pct_exact_0_or_1"}\n        for name, value in attributes.items():\n            grouped[row["variant"], row["branch"], name, value].append(row)\n    characteristics = []\n    for (variant, branch, name, value), group in grouped.items():\n        eligible = [r["within_video_auc"] for r in group if r["within_video_auc"] is not None]\n        positives, negatives = sum(r["event_frames"] for r in group), sum(r["frames"]-r["event_frames"] for r in group)\n        characteristics.append({"dataset": dataset, "variant": variant, "branch": branch,\n                                "characteristic": name, "value": value, "video_count": len(group),\n                                "eligible_auc_videos": len(eligible), "macro_within_video_auc": float(np.mean(eligible)) if eligible else None,\n                                "fp_frames_at_0_5": sum(r["fp_frames"] for r in group),\n                                "fn_frames_at_0_5": sum(r["fn_frames"] for r in group),\n                                "event_recall_at_0_5": sum(r["tp_frames"] for r in group)/positives if positives else None,\n                                "background_fpr_at_0_5": sum(r["fp_frames"] for r in group)/negatives if negatives else None,\n                                "interpretation": "descriptive association; groups overlap; no causal claim"})\n    for name, rows in (("per_video_errors.csv", all_rows), ("error_segments.csv", errors),\n                       ("event_diagnostics.csv", events), ("paired_video_errors.csv", paired),\n                       ("characteristic_summary.csv", characteristics), ("stage_evidence.csv", evidence)):\n        write_csv(output / name, rows)\n    summary = {"schema": "v21_flow_error_audit_v1", "dataset": dataset, "sources": sources,\n               "diagnostic_threshold": .5, "threshold_source": "fixed before test; uncalibrated; diagnostic only",\n               "frame_intervals": "0-based [start,end); no assumed FPS",\n               "test_annotations_scope": "post-hoc only; no model/checkpoint/threshold selection",\n               "checks_passed": ["unique video IDs", "per-video feature hashes", "same V0/treatment input grid",\n                                  "frame expansion", "binary GT", "normal label consistency", "metric replay"],\n               "trace_required": require_trace,\n               "video_branch_rows": len(all_rows), "error_segment_count": len(errors),\n               "stage_evidence_count": len(evidence),\n               "causal_diagnosis": "unresolved; observations identify where errors are visible, not the first causal stage",\n               "hypotheses_to_test": [\n                   {"if": "raw rank exceeds rounded-probability rank", "hypothesis": "score conversion loses temporal ordering",\n                    "check": "report raw-logit ranks with fixed checkpoint; separate stable native MIL-loss ablation"},\n                   {"if": "ranking already weak in raw outputs", "hypothesis": "upstream representation, head or MIL supervision may fail temporal discrimination",\n                    "check": "hold recipe fixed; ablate one adapter/fusion/pooling component at a time on development data"},\n                   {"if": "multiple-block or short-event groups regress", "hypothesis": "temporal context or sampling may be limiting",\n                    "check": "inspect saved sample indices/block boundaries; controlled train/dev exposure or window experiment"}],\n               "limits": ["cached features cannot establish scene appearance, lighting or camera motion",\n                          "training traces and test traces refer to different videos; no per-test-sample training causality",\n                          "GT-dependent characteristics are descriptive only; not model inputs"]}\n    if require_trace:\n        summary["checks_passed"].append("raw forward replay / score conversion / trim matches benchmark export")\n    (output / "error_summary.json").write_text(json.dumps(summary, indent=2, ensure_ascii=False, allow_nan=False), encoding="utf-8")\n    worst = sorted([r for r in paired if r["auc_delta_pp"] is not None], key=lambda r: r["auc_delta_pp"])[:12]\n    text = [f"# Chẩn đoán mẫu sai: {dataset}", "",\n            "Ngưỡng 0.5 cố định chỉ dùng thống kê FP/FN; chưa hiệu chỉnh xác suất. Xem thêm AUC theo video và raw logits.",\n            "Khoảng frame dùng chỉ số từ 0, đầu đóng/cuối mở. Không quy đổi giây khi chưa có FPS.", "",\n            "| Video | Nhánh | Δ AUC so V0 (đpt) | Bước quan sát lỗi |",\n            "|---|---|---:|---|"]\n    text.extend(f"| {r[\'video_id\'].split(\'/\')[-1]} | {r[\'branch\']} | {r[\'auc_delta_pp\']:+.2f} | {r[\'observed_stage\']} |" for r in worst)\n    text += ["", "Tất cả video: per_video_errors.csv. Đoạn FP/FN: error_segments.csv. Sự kiện bỏ sót: event_diagnostics.csv.",\n             "So V0: paired_video_errors.csv. Đặc điểm nhóm: characteristic_summary.csv. Bằng chứng theo bước: stage_evidence.csv.",\n             "", "Đã quan sát đầu ra sai ở bước ghi trong bảng; nguồn gây lỗi có thể nằm phía trước. Chưa chứng minh nguyên nhân gốc.",\n             "Không suy diễn nội dung hình ảnh từ tên file hoặc norm embedding. Xem error_summary.json để chọn đối chứng tiếp theo trên train/dev."]\n    (output / "ERROR_ANALYSIS.md").write_text("\\n".join(text)+"\\n", encoding="utf-8")\n    return summary\n', 'v21_recovery.py': '"""Reuse completed full-run datasets after postprocessing failures; never resume training."""\n\nimport ast\nimport hashlib\nimport json\nfrom pathlib import Path, PurePosixPath\nfrom zipfile import ZipFile\n\n\nclass RecoveryInput:\n    def __init__(self, source):\n        self.path = Path(source).expanduser().resolve()\n        if self.path.is_dir():\n            self.archive = None\n            self.names = [p.relative_to(self.path).as_posix() for p in self.path.rglob("*") if p.is_file()]\n        elif self.path.is_file() and self.path.suffix.lower() == ".zip":\n            self.archive = ZipFile(self.path)\n            self.names = [info.filename for info in self.archive.infolist() if not info.is_dir()]\n        else:\n            raise FileNotFoundError(f"RECOVERY_FROM must be the previous run directory or result ZIP: {self.path}")\n        if "experiment.json" not in self.names or len(self.names) != len(set(self.names)):\n            self.close()\n            raise ValueError("Recovery input must contain one run with experiment.json at its root")\n        for name in self.names:\n            parts = PurePosixPath(name)\n            if parts.is_absolute() or ".." in parts.parts or "\\\\" in name or ":" in name:\n                self.close()\n                raise ValueError("Unsafe recovery archive/path member")\n\n    def close(self):\n        if self.archive is not None:\n            self.archive.close()\n\n    def __enter__(self):\n        return self\n\n    def __exit__(self, *_):\n        self.close()\n\n    def read(self, name):\n        if name not in self.names:\n            raise FileNotFoundError(f"Recovery artifact missing: {name}")\n        if self.archive is not None:\n            return self.archive.read(name)\n        path = (self.path / name).resolve()\n        if not path.is_relative_to(self.path):\n            raise ValueError("Recovery file resolves outside source run")\n        return path.read_bytes()\n\n    def metadata(self, name):\n        return json.loads(self.read(name).decode("utf-8"))\n\n    def reuse(self, prefix, output, sources, train_config, geometry_config, seed, checkpoint_sha, manifest_sha, treatment):\n        """Return copied report paths only after provenance/recipe/checkpoint validation."""\n        training_name = f"{prefix}/train/training.json"\n        if training_name not in self.names:\n            return None\n        experiment = self.metadata("experiment.json")\n        if experiment.get("mode") != "full" or experiment.get("seed") != seed:\n            raise ValueError("Cannot reuse a pilot/smoke run or another seed as a full benchmark")\n        if experiment.get("geometry_config") != geometry_config:\n            raise ValueError("Recovery geometry configuration differs")\n        mutable = {"v21_error_analysis.py", "orchestrator_v21.py", "v21_recovery.py"}\n        for name, source in sources.items():\n            actual_sha = hashlib.sha256(source.encode()).hexdigest()\n            previous_sha = experiment["source_sha256"].get(name)\n            if name == "v21_diagnostics.py" and previous_sha != actual_sha:\n                previous = self.read("runtime_scripts/v21_diagnostics.py").decode("utf-8")\n                if hashlib.sha256(previous.encode()).hexdigest() != previous_sha:\n                    raise ValueError("Recovery diagnostic source does not match its manifest")\n\n                def training_contract(text):\n                    tree = ast.parse(text)\n                    tree.body = [node for node in tree.body if not\n                                 (isinstance(node, ast.ClassDef) and node.name == "EvaluationTrace")]\n                    return ast.dump(tree, include_attributes=False)\n\n                if training_contract(previous) != training_contract(source):\n                    raise ValueError("Recovery diagnostics changed training behavior; cannot reuse")\n                continue  # Only the observational inference trace class changed.\n            if name not in mutable and previous_sha != actual_sha:\n                raise ValueError(f"Recovery model/data/training source differs: {name}")\n        training = self.metadata(training_name)\n        record = training["variants"][treatment]\n        def canonical(value):\n            return json.loads(json.dumps(value))\n        if canonical(record["config"]) != canonical(train_config):\n            raise ValueError("Recovery training recipe differs; no checkpoint or metrics reused")\n        if (training.get("feature_manifest_sha256") != manifest_sha or\n                training.get("initial_v0_sha256") != checkpoint_sha or\n                record.get("initial_v0_sha256") != checkpoint_sha):\n            raise ValueError("Recovery input/checkpoint provenance differs")\n        checkpoint_name = f"{prefix}/train/{record[\'checkpoint_file\']}"\n        if hashlib.sha256(self.read(checkpoint_name)).hexdigest() != record["checkpoint_sha256"]:\n            raise ValueError("Recovery trained checkpoint SHA-256 mismatch")\n        paths = {}\n        for variant in ("v0", treatment):\n            matches = [n for n in self.names if n.startswith(f"{prefix}/{variant}/") and n.endswith("/run.json")]\n            if len(matches) != 1:\n                raise ValueError(f"Recovery has completed training but lacks one full evaluator report: {prefix}/{variant}")\n            name = matches[0]\n            report = self.metadata(name)\n            expected_sha = checkpoint_sha if variant == "v0" else record["checkpoint_sha256"]\n            if (report.get("evaluated_checkpoint_sha256") != expected_sha or\n                    report.get("initial_v0_checkpoint_sha256") != checkpoint_sha or\n                    report.get("run_kind") != "full_checkpoint_inference" or not report.get("metrics")):\n                raise ValueError(f"Recovery evaluator checkpoint/mode mismatch: {prefix}/{variant}")\n            folder = PurePosixPath(name).parent\n            for required in ("predictions.npz", "diagnostics/diagnostic_tensors.npz"):\n                if str(folder / required) not in self.names:\n                    raise ValueError(f"Recovery evaluator artifact missing: {prefix}/{variant}/{required}")\n            paths[variant] = Path(output) / name\n        copied = []\n        for name in self.names:\n            if not name.startswith(prefix + "/"):\n                continue\n            relative = PurePosixPath(name)\n            if (relative.suffix not in {".json", ".jsonl", ".csv", ".log", ".md", ".npz"}\n                    and relative.name != "best.pth"):\n                continue\n            if len(relative.parts) > 1 and relative.parts[1] == "error_analysis":\n                continue  # Rebuild with the corrected analyzer.\n            target = Path(output) / name\n            target.parent.mkdir(parents=True, exist_ok=True)\n            payload = self.read(name)\n            target.write_bytes(payload)\n            copied.append({"path": name, "sha256": hashlib.sha256(payload).hexdigest()})\n        receipt = {"source_run": self.path.name, "dataset": prefix, "source_experiment": experiment,\n                   "source_experiment_sha256": hashlib.sha256(self.read("experiment.json")).hexdigest(),\n                   "new_training": False, "new_inference": False, "postprocessing_rerun": True,\n                   "files": copied, "latency_scope": "reused original V0/treatment pair; not measured in this session"}\n        (Path(output) / prefix / "recovery_receipt.json").write_text(json.dumps(receipt, indent=2), encoding="utf-8")\n        return paths, Path(output) / training_name\n', 'orchestrator_v21.py': '"""Kaggle orchestrator; sources/config are embedded by the standalone notebook."""\n\nimport csv\nimport hashlib\nimport importlib.util\nimport json\nimport math\nimport os\nimport subprocess\nimport sys\nimport tempfile\nfrom collections import deque\nfrom pathlib import Path\nfrom zipfile import ZIP_DEFLATED, ZipFile\n\nV0_CHECKPOINT_SHA = {\n    "ucf": "d064aba05190ce5f6652151e6259b24ca6dda83a1e6289bf343afb6f905a2c79",\n    "xd": "a676c14d794a7046f7636041e601a5d9a2bef03708dbc4cae90f8b37ac2af2b4",\n}\n\n\ndef file_sha(path):\n    with Path(path).open("rb") as stream:\n        return hashlib.file_digest(stream, "sha256").hexdigest()\n\n\ndef resolve_checkpoint(prefix, override, directory):\n    candidates = [Path(override)] if override else sorted(\n        p for p in INPUT.rglob("*") if p.is_file() and (\n            p.name.lower() in {f"model_{prefix}.pth", "model.pth"}\n            or p.suffix.lower() == ".zip" and prefix in p.stem.lower()\n            and "checkpoint" in p.stem.lower()))\n    for path in candidates:\n        if path.suffix.lower() == ".pth" and file_sha(path) == V0_CHECKPOINT_SHA[prefix]:\n            return path\n        if path.suffix.lower() == ".zip":\n            with ZipFile(path) as archive:\n                for member in archive.infolist():\n                    if member.is_dir() or not member.filename.lower().endswith(".pth"):\n                        continue\n                    with archive.open(member) as stream:\n                        digest = hashlib.file_digest(stream, "sha256").hexdigest()\n                    if digest == V0_CHECKPOINT_SHA[prefix]:\n                        directory.mkdir(parents=True, exist_ok=True)\n                        target = directory / f"model_{prefix}.pth"\n                        target.write_bytes(archive.read(member))\n                        if file_sha(target) != digest:\n                            raise ValueError("Staged V0 checkpoint hash mismatch")\n                        return target\n    raise FileNotFoundError(f"Attach the original pinned {prefix} V0 checkpoint (.pth or ZIP)")\n\n\ndef load_module(name, path):\n    spec = importlib.util.spec_from_file_location(name, path)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef runner_header(config):\n    return "from pathlib import Path\\n" + "\\n".join(\n        f"{name} = " + (f"Path({str(value)!r})" if isinstance(value, Path) else repr(value))\n        for name, value in config.items()) + "\\n\\n"\n\n\ndef run_dataset(name, source, config, scripts):\n    reporting = load_module("v21_reporting", scripts / "benchmark_reporting.py")\n    reporting.save_run_config(scripts / f"{name}.config.json", config, source)\n    script = scripts / f"{name}.py"\n    script.write_text(runner_header(config) + source, encoding="utf-8")\n    print(f"\\n--- {name} ---", flush=True)\n    last_lines = deque(maxlen=40)\n    with (scripts.parent / f"{name}_console.log").open("w", encoding="utf-8") as log:\n        with subprocess.Popen([sys.executable, "-u", str(script)], stdout=subprocess.PIPE,\n                              stderr=subprocess.STDOUT, encoding="utf-8", errors="replace",\n                              env={**os.environ, "PYTHONIOENCODING": "utf-8"}) as process:\n            for line in process.stdout:\n                last_lines.append(line)\n                log.write(line)\n                print(line, end="", flush=True)\n            if process.wait() != 0:\n                detail = "".join(last_lines).strip() or "Subprocess produced no console output"\n                raise RuntimeError(f"Failed {name}; see {log.name}\\nLast output:\\n{detail}")\n    paths = list(Path(config["OUTPUT"]).rglob("run.json"))\n    for path in paths:\n        reporting.emit_report(path)\n        geometry = json.loads(path.read_text(encoding="utf-8")).get("geometry")\n        if geometry:\n            print(reporting.render_table(["Geometry setting", "Value"], [\n                [key, geometry[key]] for key in ("space", "curvature_magnitude", "lambda_visual",\n                                                "lambda_text", "temperature", "chunk_size")\n            ]), flush=True)\n    if source == TRAINER_SOURCE:\n        return Path(config["OUTPUT"]) / "training.json"\n    if len(paths) != 1:\n        raise RuntimeError(f"Expected one evaluator run.json for {name}")\n    return paths[0]\n\n\ndef verify_comparison(prefix, paths, analysis, treatment="v21"):\n    import numpy as np\n\n    reports, arrays = {}, {}\n    for name, path in paths.items():\n        reports[name] = json.loads(path.read_text(encoding="utf-8"))\n        with np.load(path.with_name("predictions.npz"), allow_pickle=False) as archive:\n            arrays[name] = dict(archive)\n    base_report, base = reports["v0"], arrays["v0"]\n    primary = "classification" if prefix == "ucf" else "branch_2"\n    metric = "roc_auc" if prefix == "ucf" else "frame_ap"\n    expected = .8801992605166816 if prefix == "ucf" else .8450448809004643\n    if abs(base_report["metrics"][primary][metric] - expected) > .00005:\n        raise ValueError("V0 does not reproduce the locked reference")\n    id_key = "video_id" if prefix == "ucf" else "official_path"\n    for name, array in arrays.items():\n        report = reports[name]\n        for key in ("initial_v0_checkpoint_sha256", "split_sha256", "ground_truth_sha256",\n                    "visual_block_length", "frames_per_feature"):\n            if report[key] != base_report[key]:\n                raise ValueError(f"Mismatched V0/variant protocol: {name}/{key}")\n        for key in (id_key, "snippet_offsets", "score_columns", "frame_gt", "video_label"):\n            if not np.array_equal(array[key], base[key]):\n                raise ValueError(f"Mismatched evaluator grid: {name}/{key}")\n        if array["scores"].shape != base["scores"].shape or not np.isfinite(array["scores"]).all():\n            raise ValueError("Invalid alignment scores")\n    rows = []\n    for column, branch in enumerate(("classification", "alignment") if prefix == "ucf"\n                                    else ("branch_1", "branch_2")):\n        control = "v0"\n        bootstrap = analysis.paired_bootstrap(\n            arrays[control]["scores"][:, column], arrays[treatment]["scores"][:, column],\n            base["frame_gt"].reshape(-1), base["snippet_offsets"], BOOTSTRAP_REPLICATES, SEED)\n        for name, boot_key in (("roc_auc", "auc_ci95_pp"),\n                               ("ap" if prefix == "ucf" else "frame_ap", "ap_ci95_pp")):\n            a, b = [reports[v]["metrics"][branch][name] * 100 for v in (control, treatment)]\n            low, high = bootstrap[boot_key] or (None, None)\n            rows.append({"dataset": prefix, "branch": branch, "metric": name,\n                         "control": control, "treatment": treatment, "control_pct": a,\n                         "treatment_pct": b, "delta_pp": b - a,\n                         "ci95_low_pp": low, "ci95_high_pp": high})\n    return rows\n\n\ndef compare_historical(prefix, path, reference):\n    """Compare saved ZIP5 metrics only after checking the same evaluator protocol."""\n    report = json.loads(path.read_text(encoding="utf-8"))\n    previous = reference["datasets"][prefix]\n    for key, expected in previous["protocol"].items():\n        if report[key] != expected:\n            raise ValueError(f"Historical evaluator protocol mismatch: {prefix}/{key}")\n    rows = []\n    for branch, metrics in previous["metrics"].items():\n        for name, value in metrics.items():\n            if name not in {"roc_auc", "ap", "frame_ap", "ano_auc"}:\n                continue\n            current = report["metrics"][branch][name]\n            rows.append({"dataset": prefix, "branch": branch, "metric": name,\n                         "reference_run": reference["run"], "reference_variant": "v21_zip5",\n                         "treatment": "cosine_control", "reference_pct": 100 * value,\n                         "treatment_pct": 100 * current, "delta_pp": 100 * (current - value),\n                         "scope": reference["scope"]})\n    return rows\n\n\ndef dataset_train_config(config, prefix):\n    resolved = dict(config)\n    rates = config.get("learning_rate_by_dataset")\n    rate = rates[prefix] if rates is not None else config["learning_rate"]\n    if isinstance(rate, bool) or not isinstance(rate, (float, int)) or not math.isfinite(rate) or rate <= 0:\n        raise ValueError(f"Invalid learning rate for {prefix}: {rate}")\n    resolved["learning_rate"] = float(rate)\n    return resolved\n\n\ndef run_both():\n    # Rerunning a failed notebook cell must not offer a stale ZIP from an earlier run.\n    globals().pop("RESULT_ZIP", None)\n    globals().pop("LAST_RESULT_ZIP", None)\n    if RUN_MODE not in {"smoke", "pilot", "full"} or not INPUT.is_dir():\n        raise ValueError("Use RUN_MODE smoke/pilot/full and attach Kaggle inputs")\n    if globals().get("RECOVERY_FROM") and RUN_MODE != "full":\n        raise ValueError("RECOVERY_FROM reuses completed full datasets; use RUN_MODE=\'full\'")\n    training_config = dict(TRAIN_CONFIG)\n    native = bool(TRAIN_CONFIG.get("native_cosine_control", False))\n    treatment = "cosine_control" if native else "v21"\n    if RUN_MODE == "pilot":\n        if not (native or TRAIN_CONFIG.get("sanity_fix")):\n            raise ValueError("Train-only pilot is supported by the Sanity Fix recipe")\n        pilot_epochs = TRAIN_CONFIG.get("pilot_epochs", 3)\n        if type(pilot_epochs) is not int or pilot_epochs < 1:\n            raise ValueError("pilot_epochs must be a positive integer")\n        training_config["epochs"] = pilot_epochs\n    if not DATASETS or len(set(DATASETS)) != len(DATASETS) or set(DATASETS) - {"ucf", "xd"}:\n        raise ValueError("DATASETS must contain ucf and/or xd without duplicates")\n    if BOOTSTRAP_REPLICATES < 1 or HALF_BATCH < 1 or TRAIN_CONFIG["epochs"] < 1:\n        raise ValueError("Invalid training/analysis budget")\n    root = WORK / "vadclip_v21"\n    root.mkdir(parents=True, exist_ok=True)\n    output = Path(tempfile.mkdtemp(prefix="run_", dir=root))\n    scripts = output / "runtime_scripts"\n    scripts.mkdir()\n    for name, source in SOURCES.items():\n        (scripts / name).write_text(source, encoding="utf-8")\n    reporting = load_module("v21_reporting", scripts / "benchmark_reporting.py")\n    analysis = load_module("v21_analysis", scripts / "analysis.py")\n    latency = load_module("v21_latency", scripts / "latency_inference.py")\n    experiment = {"version": "v21", "mode": RUN_MODE, "seed": SEED,\n                  "geometry_config": GEOMETRY_CONFIG, "train_config": training_config,\n                  "bootstrap": BOOTSTRAP_REPLICATES,\n                  "training_recipe": ("COSINE_NATIVE_LR_CONTROL" if native else\n                                      "SANITY_FIXED_C" if TRAIN_CONFIG.get("sanity_fix") else\n                                      "PAPER" if TRAIN_CONFIG.get("paper_design") else\n                                      "B" if "from_scratch" in TRAIN_CONFIG else "A"),\n                  "reproduction_disclosure": TRAIN_CONFIG.get("reproduction_disclosure"),\n                  "claim": ("native cosine run_yxfrilug recipe with only LR changed; observational traces added; pilot has its own schedule"\n                            if native else "disclosed sanity corrections; no author-exact or quality claim"\n                            if TRAIN_CONFIG.get("sanity_fix") else\n                            "published equations/settings; author-code parity unresolved"\n                            if TRAIN_CONFIG.get("paper_design") else\n                            "fresh downstream Poincare training; frozen CLIP only from V0"\n                            if "from_scratch" in TRAIN_CONFIG else\n                            "two-stage A Poincare adaptation, warm-start V0; CLIP frozen"),\n                  "cosine_control_trained": False,\n                  "trained_variant": treatment,\n                  "full_poinclip_reproduction": False, "open_vocabulary": False,\n                  "source_sha256": {name: hashlib.sha256(source.encode()).hexdigest()\n                                    for name, source in SOURCES.items()}}\n    (output / "experiment.json").write_text(json.dumps(experiment, indent=2), encoding="utf-8")\n    shared = {"INPUT": INPUT, "WORK": WORK, "CLIP_WEIGHTS": CLIP_WEIGHTS,\n              "SRC_REPO": Path(tempfile.gettempdir()) / "vadclip_xd_c41067f" / "upstream",\n              "SMOKE_ONLY": RUN_MODE == "smoke", "LATENCY_WARMUP": LATENCY_WARMUP,\n              "LATENCY_REPEATS": LATENCY_REPEATS, "GEOMETRY_CONFIG": GEOMETRY_CONFIG}\n    jobs = {\n        "ucf": (UCF_RUNNER, UCF_TRAIN_ROOT, UCF_CHECKPOINT, {"DATA_ROOT": UCF_DATA_ROOT}),\n        "xd": (XD_RUNNER, XD_TRAIN_ROOT, XD_CHECKPOINT,\n               {"DATA_ROOT": XD_DATA_ROOT, "FEATURE_ZIP": XD_FEATURE_ZIP,\n                "REFERENCE_MANIFEST": None, "REQUIRE_PACK_MANIFEST": True, "RUN_MODE": RUN_MODE}),\n    }\n    results, comparisons, historical_rows = {}, [], []\n    if native and globals().get("ZIP5_REFERENCE"):\n        (output / "historical_reference.json").write_text(\n            json.dumps(ZIP5_REFERENCE, indent=2), encoding="utf-8")\n    print("Output:", output, flush=True)\n    for prefix in DATASETS:\n        runner, train_root, override, inputs = jobs[prefix]\n        paths = {}\n        entry = results[prefix] = {"status": "running", "reports": {}}\n        try:\n            resolved_train_config = dataset_train_config(training_config, prefix)\n            entry["resolved_learning_rate"] = resolved_train_config["learning_rate"]\n            checkpoint = resolve_checkpoint(prefix, override, output / prefix / "v0_input")\n            evaluation = {**shared, **inputs, "CHECKPOINT": checkpoint}\n            reused = None\n            if globals().get("RECOVERY_FROM"):\n                recovery = load_module("v21_recovery", scripts / "v21_recovery.py")\n                with recovery.RecoveryInput(RECOVERY_FROM) as old_run:\n                    reused = old_run.reuse(prefix, output, SOURCES, resolved_train_config,\n                                           GEOMETRY_CONFIG, SEED, V0_CHECKPOINT_SHA[prefix],\n                                           TRAIN_MANIFESTS[prefix], treatment)\n                if reused is not None:\n                    paths, trained_path = reused\n                    entry["reports"] = {name: path.relative_to(output).as_posix() for name,path in paths.items()}\n                    entry["reused_completed_dataset"] = True\n                    entry["recovery_receipt"] = f"{prefix}/recovery_receipt.json"\n                    print(f"{prefix}: reusing completed training and evaluation; rerunning diagnostics.", flush=True)\n\n            def evaluate(name, space=None, weights=None, expected_hash=None):\n                path = run_dataset(f"{prefix}_{name}", runner, {\n                    **evaluation, "OUTPUT": output / prefix / name, "VARIANT": name,\n                    "V21_SPACE": space, "V21_MODEL_PATH": weights,\n                    "V21_MODEL_SHA256": expected_hash,\n                }, scripts)\n                paths[name] = path\n                entry["reports"][name] = path.relative_to(output).as_posix()\n\n            if RUN_MODE != "pilot" and reused is None:\n                evaluate("v0")\n            if RUN_MODE == "full":\n                baseline = json.loads(paths["v0"].read_text(encoding="utf-8"))\n                branch, metric, expected = (("classification", "roc_auc", .8801992605166816)\n                                            if prefix == "ucf" else\n                                            ("branch_2", "frame_ap", .8450448809004643))\n                if abs(baseline["metrics"][branch][metric] - expected) > .00005:\n                    raise ValueError("V0 reference mismatch; training has not been started")\n            train_output = output / prefix / "train"\n            if reused is None:\n                trained_path = run_dataset(f"{prefix}_train", TRAINER_SOURCE, {\n                    **shared, "OUTPUT": train_output, "PREFIX": prefix, "TRAIN_ROOT": train_root,\n                    "V0_PATH": checkpoint, "V0_SHA256": V0_CHECKPOINT_SHA[prefix],\n                    "MANIFEST_SHA256": TRAIN_MANIFESTS[prefix], "SEED": SEED,\n                    "HALF_BATCH": HALF_BATCH, "TRAIN_CONFIG": resolved_train_config,\n                    "RUN_MODE": RUN_MODE,\n                }, scripts)\n            trained = json.loads(trained_path.read_text(encoding="utf-8"))\n            entry["training"] = trained_path.relative_to(output).as_posix()\n            if native and RUN_MODE == "full" and globals().get("ZIP5_REFERENCE"):\n                for key, expected in ZIP5_REFERENCE["datasets"][prefix]["training"].items():\n                    if trained.get(key) != expected:\n                        raise ValueError(f"Historical training input mismatch: {prefix}/{key}")\n            entry["cosine_control_trained"] = native\n            if native:\n                experiment["cosine_control_trained"] = all(\n                    results.get(ds, {}).get("cosine_control_trained", False) for ds in DATASETS)\n            for name in (treatment,):\n                record = trained["variants"][name]\n                weights = train_output / record["checkpoint_file"]\n                if RUN_MODE != "pilot" and reused is None:\n                    evaluate(name, record["space"], weights, record["checkpoint_sha256"])\n            if RUN_MODE == "full":\n                comparisons.extend(verify_comparison(prefix, paths, analysis, treatment)\n                                   if native else verify_comparison(prefix, paths, analysis))\n                if native and globals().get("ZIP5_REFERENCE"):\n                    historical_rows.extend(compare_historical(prefix, paths[treatment], ZIP5_REFERENCE))\n                diagnostic = load_module("v21_error_analysis", scripts / "v21_error_analysis.py")\n                diagnosis = diagnostic.analyze_benchmark(prefix, paths, output / prefix / "error_analysis")\n                entry["error_analysis"] = f"{prefix}/error_analysis/error_summary.json"\n                entry["error_segments"] = diagnosis["error_segment_count"]\n            entry["status"] = "ok"\n        except Exception as exc:  # Preserve partial outputs; never treat failure as success.\n            entry.update(status="failed", error=f"{type(exc).__name__}: {exc}")\n            print(prefix, entry["error"], flush=True)\n        finally:\n            (output / "summary.json").write_text(json.dumps({\n                **experiment, "runs": results, "branch_comparisons": comparisons,\n            }, indent=2), encoding="utf-8")\n        if entry["status"] == "failed" and STOP_ON_FAILURE:\n            print("Stopping after failed dataset; saving partial ZIP.", flush=True)\n            break\n    postprocessing_errors = []\n    collectors = (() if RUN_MODE == "pilot" else\n                  (("reporting", reporting.collect_reports), ("latency", latency.collect_latency)))\n    if RUN_MODE == "pilot":\n        print("Train-only pilot complete; official test/latency not evaluated. Inspect learning_health.json.",\n              flush=True)\n    for name, collect in collectors:\n        try:\n            collect(output)\n        except Exception as exc:\n            postprocessing_errors.append({"step": name, "error": f"{type(exc).__name__}: {exc}"})\n            print("Postprocessing failed:", postprocessing_errors[-1], flush=True)\n    (output / "summary.json").write_text(json.dumps({\n        **experiment, "runs": results, "branch_comparisons": comparisons,\n        "postprocessing_errors": postprocessing_errors,\n    }, indent=2), encoding="utf-8")\n    if comparisons:\n        with (output / "branch_comparison.csv").open("w", newline="", encoding="utf-8") as stream:\n            writer = csv.DictWriter(stream, fieldnames=list(comparisons[0]))\n            writer.writeheader()\n            writer.writerows(comparisons)\n        print(reporting.render_table(\n            ["Dataset", "Branch", "Metric", "Control", "Treatment", "Delta pp", "CI95 pp"],\n            [[r["dataset"], r["branch"], r["metric"], r["control"], r["treatment"], f"{r[\'delta_pp\']:+.5f}",\n              ("N/A" if r["ci95_low_pp"] is None else\n               f"[{r[\'ci95_low_pp\']:+.5f}, {r[\'ci95_high_pp\']:+.5f}]")]\n             for r in comparisons],\n            numeric=(5, 6)), flush=True)\n    if historical_rows:\n        with (output / "historical_comparison.csv").open("w", newline="", encoding="utf-8") as stream:\n            writer = csv.DictWriter(stream, fieldnames=list(historical_rows[0]))\n            writer.writeheader()\n            writer.writerows(historical_rows)\n        print("Historical ZIP5 comparison saved: historical_comparison.csv; heads/objective differ.",\n              flush=True)\n    archive_path = output / "vadclip_v21_results.zip"\n    with ZipFile(archive_path, "w", ZIP_DEFLATED) as archive:\n        for path in sorted(output.rglob("*")):\n            if path.is_file() and (path.suffix in {".json", ".jsonl", ".csv", ".py", ".log", ".md"}\n                                   or path.name == "best.pth"\n                                   or path.name == "diagnostic_tensors.npz"\n                                   or INCLUDE_PREDICTIONS and path.name == "predictions.npz"):\n                archive.write(path, path.relative_to(output))\n    globals()["LAST_RESULT_ZIP"] = archive_path\n    print("Download:", archive_path, flush=True)\n    if postprocessing_errors or any(result["status"] != "ok" for result in results.values()):\n        reasons = [f"{dataset}: {record.get(\'error\', \'incomplete\')}"\n                   for dataset, record in results.items() if record["status"] != "ok"]\n        reasons.extend(f"{item[\'step\']}: {item[\'error\']}" for item in postprocessing_errors)\n        raise RuntimeError(f"Incomplete V21 run. Partial results saved in {archive_path}\\n"\n                           + "\\n".join(reasons))\n    return archive_path\n\n\n# Notebook imports the embedded sources/config before this cell.\n# ruff: noqa: F821\nRESULT_ZIP = run_both()\n'})
UCF_RUNNER = '\nCOMMIT = "c41067f07d252efcda18008bea367886070c33b0"\nUPSTREAM_URL = "https://github.com/nwpu-zxr/VadCLIP.git"\nEXPECTED_INPUTS = {\n    "checkpoint_sha256": "d064aba05190ce5f6652151e6259b24ca6dda83a1e6289bf343afb6f905a2c79",\n    "split_sha256": "d621f4ccfb3e26274d215ad53b83fd1f596bb7e9f85cde69e01399db3da97c7f",\n    "ground_truth_sha256": "c6448801e0f73d19adf82506cd58d60a90c4f0913e49dcc1ad1d677ee12d6301",\n    "annotation_sha256": "82d581cd4685480ffda23eb0fe1bca441b672bfe99c457adca2df4cf4780c503",\n    "feature_inventory_sha256": "8aa3a3c58f9bbbcc8082e024f3892e014f059374e8b52ca737ae709945210026"\n}\n\nimport csv\nimport hashlib\nimport importlib.util\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nimport tempfile\nimport time\nfrom collections import defaultdict\nfrom shutil import copyfile, copyfileobj, copytree\nfrom urllib.error import URLError\nfrom zipfile import BadZipFile, ZipFile\n\nif not INPUT.is_dir():\n    raise FileNotFoundError("Import notebook trên Kaggle và gắn input trước.")\n\ndef git(*args):\n    return subprocess.check_output(["git", *map(str, args)], text=True).strip()\n\n\nif not SRC_REPO.exists():\n    SRC_REPO.parent.mkdir(parents=True, exist_ok=True)\n    with tempfile.TemporaryDirectory(dir=SRC_REPO.parent) as checkout_dir:\n        checkout = Path(checkout_dir) / "source"\n        subprocess.run(["git", "clone", UPSTREAM_URL, str(checkout)], check=True)\n        subprocess.run(["git", "-C", str(checkout), "checkout", "--detach", COMMIT], check=True)\n        checkout.rename(SRC_REPO)\nif git("-C", SRC_REPO, "rev-parse", "HEAD") != COMMIT:\n    raise RuntimeError(f"Mã nguồn tại {SRC_REPO} sai commit. Hãy dùng thư mục nguồn mới.")\nif git("-C", SRC_REPO, "status", "--porcelain", "--untracked-files=no"):\n    raise RuntimeError(f"Mã nguồn tại {SRC_REPO} có thay đổi. Hãy dùng checkout sạch.")\n\npackages = {\n    "ftfy": "ftfy", "packaging": "packaging", "regex": "regex",\n    "tqdm": "tqdm", "sklearn": "scikit-learn",\n}\nmissing_packages = [pkg for mod, pkg in packages.items() if importlib.util.find_spec(mod) is None]\nif missing_packages:\n    subprocess.run([sys.executable, "-m", "pip", "install", *missing_packages], check=True)\n\nnp = importlib.import_module("numpy")\n\n# Modern setuptools no longer ships pkg_resources. Adapt the import in a copy.\nstage_directory = tempfile.TemporaryDirectory(prefix="vadclip_ucf_v5_")\nstaging = Path(stage_directory.name)\nruntime_src = staging / "runtime"\ncopytree(SRC_REPO / "src", runtime_src, dirs_exist_ok=True)\nfrom v7_windows import overlap_forward\n\nclip_py = runtime_src / "clip" / "clip.py"\nclip_source = clip_py.read_text(encoding="utf-8")\nold_import = "from pkg_resources import packaging"\nif clip_source.count(old_import) != 1:\n    raise RuntimeError("Không tìm thấy import CLIP cần sửa tương thích. Kiểm commit.")\nclip_py.write_text(clip_source.replace(old_import, "import packaging.version"), encoding="utf-8")\n\nOUTPUT.mkdir(parents=True, exist_ok=True)\nprint("Commit VadCLIP", COMMIT)\nprint(f"Chấm UCF-Crime: {VARIANT}")\n\nCLASSES = (\n    "Normal", "Abuse", "Arrest", "Arson", "Assault", "Burglary", "Explosion",\n    "Fighting", "RoadAccidents", "Robbery", "Shooting", "Shoplifting", "Stealing", "Vandalism",\n)\nFRAMES_PER_FEATURE = 16\nFEATURE_DIM = 512\nVIDEO_COUNT = 290\nCLIP_SHA256 = "5806e77cd80f8b59890b7e101eabd078d9fb84e6937f9e85e4ecb61988df416f"\n\n\ndef sha256(path):\n    with path.open("rb") as stream:\n        return hashlib.file_digest(stream, "sha256").hexdigest()\n\n\ndef read_split(list_root):\n    """Đọc theo đúng thứ tự repo. Tính khoảng [start, end) theo frame gốc."""\n    with (list_root / "ucf_CLIP_rgbtest.csv").open(newline="", encoding="utf-8") as stream:\n        entries = list(csv.DictReader(stream))\n    annotations = {}\n    for line in (list_root / "Temporal_Anomaly_Annotation.txt").read_text().splitlines():\n        if not line.strip():\n            continue\n        name, label, *bounds = line.split()\n        video_id = Path(name).stem\n        if len(bounds) != 4 or video_id in annotations:\n            raise ValueError(f"Annotation không hợp lệ: {video_id}")\n        intervals = []\n        for start, end in zip(bounds[::2], bounds[1::2]):\n            lo, hi = int(start), int(end)\n            if (lo, hi) == (-1, -1):\n                continue\n            if not 0 <= lo < hi:\n                raise ValueError(f"Khoảng frame không hợp lệ: {video_id} {(lo, hi)}")\n            intervals.append((lo, hi))\n        annotations[video_id] = (label, intervals)\n\n    rows = []\n    for entry in entries:\n        feature_name = Path(entry["path"]).name\n        match = re.fullmatch(r"(.+)__([0-9])\\.npy", feature_name)\n        if match is None:\n            raise ValueError(f"Tên feature sai: {feature_name}")\n        video_id, crop = match.groups()\n        label, intervals = annotations[video_id]\n        if label != entry["label"] or label not in CLASSES:\n            raise ValueError(f"Nhãn không khớp giữa CSV và annotation: {video_id}")\n        rows.append({\n            "id": video_id, "label": label, "feature_name": feature_name,\n            "crop": int(crop), "intervals": intervals,\n        })\n    if len(rows) != VIDEO_COUNT or len({row["id"] for row in rows}) != VIDEO_COUNT:\n        raise ValueError("Cần đúng 290 ID duy nhất từ split UCF-Crime chính thức.")\n    return rows\n\n\n\ndef stage_member(archive, member, destination):\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    with archive.open(member) as source, destination.open("wb") as target:\n        copyfileobj(source, target, length=1024 * 1024)\n    return destination\n\n\ndef find_inputs(root, keys):\n    """Tìm theo tên file chính thức, kể cả khi Kaggle giữ ZIP nguyên gói."""\n    found = defaultdict(list)\n    if root.is_file():\n        archive_path = root\n    elif root.is_dir():\n        for folder, _, filenames in os.walk(root):\n            for name in filenames:\n                key = name.casefold()\n                if key in keys:\n                    found[key].append(Path(folder) / name)\n        if found:\n            return found\n        archives = sorted(root.rglob("ucfclipfeatures_test290.zip"))\n        if len(archives) != 1:\n            raise RuntimeError(\n                "Gắn Dataset feature UCF-Crime của V0 hoặc chỉ định DATA_ROOT."\n            )\n        archive_path = archives[0]\n    else:\n        raise FileNotFoundError(f"Không thấy DATA_ROOT: {root}")\n\n    with ZipFile(archive_path) as archive:\n        for index, member in enumerate(archive.infolist()):\n            name = Path(member.filename).name\n            key = name.casefold()\n            if not member.is_dir() and key in keys:\n                destination = staging / "features" / str(index) / name\n                found[key].append(stage_member(archive, member, destination))\n    return found\n\n\ndef checkpoint_candidates():\n    if CHECKPOINT is not None:\n        path = Path(CHECKPOINT)\n        if not path.is_file():\n            raise FileNotFoundError(f"UCF_CHECKPOINT không trỏ đến file đang gắn: {path}")\n        return [path]\n\n    candidates = []\n    for path in INPUT.rglob("*"):\n        if path.suffix.lower() not in {".pth", ".zip"}:\n            continue\n        name = path.stem.casefold()\n        is_ucf_checkpoint = name.startswith("model_ucf") or ("ucf" in name and "checkpoint" in name)\n        if is_ucf_checkpoint and path.is_file():\n            candidates.append(path)\n    return sorted(candidates, key=lambda path: (path.suffix.lower() == ".zip", str(path)))\n\n\ndef choose_checkpoint():\n    expected = EXPECTED_INPUTS["checkpoint_sha256"]\n    candidates = checkpoint_candidates()\n    if not candidates:\n        raise FileNotFoundError(\n            "Không thấy checkpoint UCF trong /kaggle/input. Vào Add Input và gắn Dataset có "\n            "model_ucf.pth hoặc vadclip_ucf_checkpoint_upload.zip. Nếu tên khác, "\n            "đặt UCF_CHECKPOINT thành đường dẫn đầy đủ của file."\n        )\n\n    rejected = []\n    for path in candidates:\n        try:\n            if path.suffix.lower() == ".zip":\n                with ZipFile(path) as archive:\n                    members = [\n                        item for item in archive.infolist()\n                        if not item.is_dir() and Path(item.filename).name.casefold() == "model_ucf.pth"\n                    ]\n                    for member in members:\n                        with archive.open(member) as stream:\n                            digest = hashlib.file_digest(stream, "sha256").hexdigest()\n                        if digest == expected:\n                            print(f"Checkpoint UCF V0 khớp SHA-256: {path} ({member.filename})")\n                            return stage_member(archive, member, staging / "checkpoint" / "model_ucf.pth")\n                rejected.append(f"{path.name} không chứa model_ucf.pth khớp SHA-256")\n            elif sha256(path) == expected:\n                print(f"Checkpoint UCF V0 khớp SHA-256: {path}")\n                return path\n            else:\n                rejected.append(f"{path.name} sai SHA-256")\n        except (BadZipFile, OSError) as exc:\n            rejected.append(f"{path.name}: {exc}")\n    raise ValueError("Không tìm được checkpoint UCF đúng hash V0. " + "; ".join(rejected))\n\n\ndef input_fingerprint(rows, list_root, checkpoint_path):\n    inventory = [[row["id"], row["label"], row["steps"], row["feature_sha256"]] for row in rows]\n    inventory_bytes = json.dumps(inventory, separators=(",", ":")).encode()\n    return {\n        "checkpoint_sha256": sha256(checkpoint_path),\n        "split_sha256": sha256(list_root / "ucf_CLIP_rgbtest.csv"),\n        "ground_truth_sha256": sha256(list_root / "gt_ucf.npy"),\n        "annotation_sha256": sha256(list_root / "Temporal_Anomaly_Annotation.txt"),\n        "feature_inventory_sha256": hashlib.sha256(inventory_bytes).hexdigest(),\n    }\n\n\ndef prepare_clip_cache(source, cache_dir):\n    """Đặt file OpenAI đã xác minh vào đúng cache mà loader gốc đọc."""\n    if not source.is_file():\n        raise FileNotFoundError(f"Không thấy CLIP_WEIGHTS: {source}")\n    if sha256(source) != CLIP_SHA256:\n        raise ValueError("CLIP_WEIGHTS sai SHA-256 của OpenAI ViT-B-16.pt.")\n    target = cache_dir / "ViT-B-16.pt"\n    if target.is_file() and sha256(target) == CLIP_SHA256:\n        return target\n    cache_dir.mkdir(parents=True, exist_ok=True)\n    temporary = cache_dir / "ViT-B-16.pt.vadclip-part"\n    copyfile(source, temporary)\n    if sha256(temporary) != CLIP_SHA256:\n        raise ValueError("Bản sao CLIP lỗi. Kiểm dung lượng và file input.")\n    temporary.replace(target)\n    return target\n\n\ndef feature_array(path):\n    array = np.load(path, mmap_mode="r", allow_pickle=False)\n    if array.ndim != 2 or array.shape[1] != FEATURE_DIM or array.shape[0] < 1:\n        raise ValueError(f"Feature cần dạng [T, 512], nhận {array.shape}: {path}")\n    if array.dtype not in (np.float16, np.float32, np.float64):\n        raise ValueError(f"Feature phải là số thực, nhận {array.dtype}: {path}")\n    return array\n\n\ndef frame_labels(row, length):\n    labels = np.zeros(length, dtype=np.uint8)\n    for start, end in row["intervals"]:\n        labels[start:end] = 1\n    return labels\n\n\ndef validate_ground_truth(rows, gt):\n    """Kiểm cả nội dung và thứ tự, ngoài phép kiểm tổng số frame."""\n    offset = 0\n    for row in rows:\n        stop = offset + row["steps"] * FRAMES_PER_FEATURE\n        expected = frame_labels(row, stop - offset)\n        if not np.array_equal(gt[offset:stop], expected):\n            raise ValueError(\n                f"Ground truth lệch tại {row[\'id\']} (frame offset {offset}, "\n                f"{row[\'steps\']} bước). Kiểm lại bản video/feature và frame count."\n            )\n        offset = stop\n    if offset != len(gt):\n        raise ValueError(f"Số frame không khớp: input={offset}, ground truth={len(gt)}")\n\n# Kiểm đầu vào và đối chiếu hash với V0 đã chạy.\nlist_root = SRC_REPO / "list"\nrows = read_split(list_root)\ndata_root = Path(DATA_ROOT) if DATA_ROOT is not None else INPUT\nexpected = {row["feature_name"].casefold(): row["feature_name"] for row in rows}\nfound = find_inputs(data_root, expected)\nmissing = sorted(expected[key] for key in expected if not found[key])\nambiguous = {\n    expected[key]: [str(path) for path in sorted(found[key])]\n    for key in expected if len(found[key]) > 1\n}\nif missing or ambiguous:\n    issue_path = OUTPUT / "input_issues.json"\n    issue_path.write_text(json.dumps({\n        "missing": missing,\n        "ambiguous": ambiguous,\n    }, indent=2), encoding="utf-8")\n    raise RuntimeError(\n        f"Thiếu {len(missing)} file, trùng {len(ambiguous)} ID. "\n        f"Xem {issue_path} và kiểm DATA_ROOT."\n    )\nfor row in rows:\n    path = found[row["feature_name"].casefold()][0]\n    row["path"] = path\n    row["steps"] = len(feature_array(path))\n    row["feature_sha256"] = sha256(path)\n\ngt = np.load(list_root / "gt_ucf.npy", allow_pickle=False)\nif gt.ndim != 1 or set(np.unique(gt)) != {0.0, 1.0}:\n    raise ValueError("Ground truth UCF cần vector nhị phân cấp frame.")\nvalidate_ground_truth(rows, gt)\ncheckpoint_path = choose_checkpoint()\ninput_hashes = input_fingerprint(rows, list_root, checkpoint_path)\nmismatches = [key for key, value in EXPECTED_INPUTS.items() if input_hashes[key] != value]\nif mismatches:\n    raise ValueError("Đầu vào khác lượt V0 đã đối chiếu: " + ", ".join(mismatches))\nprint(f"Đã khớp {len(rows)} video, {len(gt):,} frame và toàn bộ hash đầu vào với V0.")\n\nimport torch\n\nsys.path.insert(0, str(runtime_src))\nfrom model import CLIPVAD\nfrom ucf_option import parser as ucf_parser\nfrom utils.tools import get_batch_mask\n\nif not torch.cuda.is_available():\n    raise RuntimeError("Hãy bật GPU trong Kaggle. Mã VadCLIP gốc cần CUDA khi chạy forward.")\ndevice = torch.device("cuda:0")\ntorch.cuda.set_device(device)\ntorch.manual_seed(234)\n\n# Dùng đúng cấu hình UCF từ mã tác giả, không đọc cờ của kernel Jupyter.\nargs = ucf_parser.parse_args([])\nevaluated_checkpoint = checkpoint_path\nevaluated_sha256 = sha256(evaluated_checkpoint)\nstate = torch.load(evaluated_checkpoint, map_location="cpu", weights_only=True)\nif isinstance(state, dict):\n    for field in ("state_dict", "model_state_dict"):\n        if field in state:\n            state = state[field]\n            break\nif CLIP_WEIGHTS is not None:\n    prepare_clip_cache(Path(CLIP_WEIGHTS), Path.home() / ".cache" / "clip")\ntry:\n    model = CLIPVAD(\n        args.classes_num, args.embed_dim, args.visual_length, args.visual_width, args.visual_head,\n        args.visual_layers, args.attn_window, args.prompt_prefix, args.prompt_postfix, device,\n    )\nexcept URLError as exc:\n    raise RuntimeError(\n        "Không tải được CLIP ViT-B/16. Bật Internet hoặc gắn ViT-B-16.pt chính thức "\n        "và đặt CLIP_WEIGHTS bằng đường dẫn file."\n    ) from exc\ntry:\n    model.load_state_dict(state, strict=True)\nexcept (RuntimeError, TypeError) as exc:\n    raise RuntimeError(\n        f"Checkpoint không khớp model VadCLIP UCF-Crime: {evaluated_checkpoint}. "\n        "Kiểm lại file từ cột Model dòng UCF-Crime, khác file ViT-B-16.pt."\n    ) from exc\ndel state\nmodel.to(device).eval()\nfrom v21_model import load_full_model\nfrom v21_native import load_native_model\n\nfull_model, full_provenance = None, None\nif V21_SPACE == "native_cosine":\n    full_model, full_provenance = load_native_model(\n        model, V21_MODEL_PATH, V21_MODEL_SHA256, evaluated_sha256, device)\n    model.forward = full_model.forward\nelif V21_SPACE is not None:\n    full_model, full_provenance = load_full_model(\n        model, V21_SPACE, GEOMETRY_CONFIG, V21_MODEL_PATH, V21_MODEL_SHA256,\n        evaluated_sha256, device)\n    model.forward = full_model.forward\nprint("Đã nạp đầy đủ checkpoint trên", torch.cuda.get_device_name(device))\n\nfrom latency_inference import InferenceLatency\n\nlatency = InferenceLatency(LATENCY_WARMUP, LATENCY_REPEATS)\nfrom v21_diagnostics import EvaluationTrace\nflow_trace = EvaluationTrace(OUTPUT / ("smoke" if SMOKE_ONLY else "full") / "diagnostics", "ucf", VARIANT)\n\n\ndef predict_video(feature, model, device, block_length, video_id):\n    """Trả điểm [T, 2], lần lượt sigmoid(C) và 1-softmax(A)[Normal]."""\n    steps = len(feature)\n    if steps < 1 or not np.isfinite(feature).all():\n        raise ValueError("Feature rỗng hoặc chứa NaN/Inf.")\n    blocks = (steps + block_length - 1) // block_length\n    padded = np.zeros((blocks * block_length, FEATURE_DIM), dtype=np.float32)\n    padded[:steps] = feature\n    lengths = torch.tensor([\n        min(block_length, steps - i * block_length) for i in range(blocks)\n    ])\n    visual = torch.from_numpy(padded.reshape(blocks, block_length, FEATURE_DIM)).to(device)\n    mask = get_batch_mask(lengths, block_length).to(device)\n    with torch.no_grad():\n        def dispatch():\n            if VARIANT == "v7":\n                t, logits_c, logits_a = overlap_forward(\n                    model, visual, mask, list(CLASSES), lengths, get_batch_mask,\n                )\n            else:\n                t, logits_c, logits_a = model(visual, mask, list(CLASSES), lengths)\n            return t, logits_c, logits_a\n\n        measured = latency.measure(\n            dispatch, device, len(latency.rows) // LATENCY_REPEATS,\n            steps, visual.shape, visual.dtype,\n        )\n        _, logits_c, logits_a = measured\n        flow_trace.observe(video_id, model, dispatch, visual, lengths, mask, measured, steps,\n                           getattr(full_model, "geometry", None), list(CLASSES), expected_features=feature)\n        c_score = logits_c.reshape(-1)[:steps].sigmoid()\n        a_score = 1 - logits_a.reshape(-1, len(CLASSES))[:steps].softmax(dim=-1)[:, 0]\n        scores = torch.stack((c_score, a_score), dim=1).cpu().numpy()\n    if scores.shape != (steps, 2) or not np.isfinite(scores).all():\n        raise ValueError(f"Điểm bất thường không hợp lệ: {scores.shape}")\n    return scores\n\n\ndef run_video(row):\n    feature = feature_array(row["path"])\n    if feature.shape != (row["steps"], FEATURE_DIM):\n        raise ValueError(f"Feature {row[\'id\']} sai shape: {feature.shape}")\n    scores = predict_video(feature, model, device, args.visual_length, row["id"])\n    for timing in latency.rows[-LATENCY_REPEATS:]:\n        timing["video_id"] = row["id"]\n    return scores\n\n\n# Chọn theo thứ tự split và độ dài, trước khi xem điểm.\npilot = sorted({\n    next(i for i, row in enumerate(rows) if row["label"] != "Normal"),\n    next(i for i, row in enumerate(rows) if row["label"] == "Normal"),\n    max(range(len(rows)), key=lambda i: rows[i]["steps"]),\n})\ntorch.cuda.reset_peak_memory_stats(device)\nstarted = time.perf_counter()\nscores_by_index = {}\nfor i in pilot:\n    before = time.perf_counter()\n    scores_by_index[i] = run_video(rows[i])\n    print(rows[i]["id"], scores_by_index[i].shape, f"{time.perf_counter() - before:.2f}s")\nsmoke_seconds = time.perf_counter() - started\nprint(f"Smoke test hoàn tất trong {smoke_seconds:.2f}s.")\n\nif not SMOKE_ONLY:\n    for i, row in enumerate(rows):\n        if i not in scores_by_index:\n            scores_by_index[i] = run_video(row)\n        if (i + 1) % 25 == 0 or i + 1 == len(rows):\n            print(f"Đã chạy {i + 1}/{len(rows)} video", flush=True)\n\nfrom importlib.metadata import version\n\nfrom sklearn.metrics import average_precision_score, roc_auc_score\n\nSCORE_COLUMNS = ("classification", "alignment")\n\n\n\n\ndef score_benchmark(rows, snippet_scores, gt):\n    steps_per_video = np.asarray([row["steps"] for row in rows])\n    if snippet_scores.shape != (sum(steps_per_video), len(SCORE_COLUMNS)):\n        raise ValueError("Số điểm snippet hoặc cột không khớp.")\n    frame_scores = np.repeat(snippet_scores, FRAMES_PER_FEATURE, axis=0)\n    if len(frame_scores) != len(gt):\n        raise ValueError("Số điểm cấp frame không khớp ground truth.")\n    frame_mask = np.repeat(\n        [row["label"] != "Normal" for row in rows],\n        steps_per_video * FRAMES_PER_FEATURE,\n    )\n    metrics = {}\n    for column, name in enumerate(SCORE_COLUMNS):\n        scores = frame_scores[:, column]\n        metrics[name] = {\n            "roc_auc": float(roc_auc_score(gt, scores)),\n            "ap": float(average_precision_score(gt, scores)),\n            "ano_auc": float(roc_auc_score(gt[frame_mask], scores[frame_mask])),\n        }\n    return metrics\n\n\nflow_trace.finish()\nselected = sorted(scores_by_index)\nif not SMOKE_ONLY and selected != list(range(len(rows))):\n    raise ValueError("Thiếu dự đoán. Cần chạy toàn bộ split trước khi chấm.")\nselected_rows = [rows[i] for i in selected]\nordered = [scores_by_index[i] for i in selected]\nif any(score.shape != (row["steps"], 2)\n       for row, score in zip(selected_rows, ordered, strict=True)):\n    raise ValueError("Số điểm từng video không khớp.")\nsteps_per_video = [row["steps"] for row in selected_rows]\nscores = np.concatenate(ordered, axis=0)\n\noutput_dir = OUTPUT / ("smoke" if SMOKE_ONLY else "full")\noutput_dir.mkdir(parents=True, exist_ok=True)\nlatency_summary = latency.save(\n    output_dir, "ucf", VARIANT, "smoke" if SMOKE_ONLY else "full", device,\n)\nfrom benchmark_reporting import count_parameters\n\nmetadata = {\n    "parameters": count_parameters(model, (full_model.geometry,) if hasattr(full_model, "geometry") else None),\n    "geometry": full_model.geometry.receipt() if hasattr(full_model, "geometry") else None,\n    "model_control": full_model.model_receipt() if V21_SPACE == "native_cosine" else None,\n    "full_model_provenance": full_provenance,\n    "run_kind": "smoke_inference" if SMOKE_ONLY else "full_checkpoint_inference",\n    "benchmark_scope": "ucf_crime_official_test",\n    "evaluation_status": "exploratory_on_previously_seen_official_test",\n    "commit": COMMIT,\n    "runtime_patch": "CLIP imports packaging.version directly",\n    **input_hashes,\n    "clip_backbone_sha256": CLIP_SHA256,\n    "frames_per_feature": FRAMES_PER_FEATURE,\n    "visual_block_length": args.visual_length,\n    "label_order": CLASSES,\n    "score_columns": SCORE_COLUMNS,\n    "initial_v0_checkpoint_sha256": evaluated_sha256,\n    "evaluated_checkpoint_sha256": V21_MODEL_SHA256 if full_model else evaluated_sha256,\n    "python": sys.version.split()[0],\n    "libraries": {name: version(name) for name in (\n        "torch", "torchvision", "numpy", "scipy", "scikit-learn", "pillow",\n    )},\n    "cuda": torch.version.cuda,\n    "gpu": torch.cuda.get_device_name(device),\n    "latency": latency_summary,\n    "smoke_seconds": smoke_seconds,\n    "inference_seconds": time.perf_counter() - started,\n    "peak_torch_vram_mib": torch.cuda.max_memory_allocated(device) / (1024 ** 2),\n    "video_count": len(selected_rows),\n    "videos": [{key: value for key, value in row.items() if key != "path"}\n               for row in selected_rows],\n    "metrics": None,\n}\nif not SMOKE_ONLY:\n    metrics = score_benchmark(rows, scores, gt)\n    metadata["metrics"] = metrics\n    print("UCF metrics saved; formatted table follows.", flush=True)\n\nnp.savez_compressed(\n    output_dir / "predictions.npz",\n    video_id=np.asarray([row["id"] for row in selected_rows]),\n    video_label=np.asarray([row["label"] for row in selected_rows]),\n    snippet_offsets=np.cumsum([0] + steps_per_video),\n    score_columns=np.asarray(SCORE_COLUMNS),\n    scores=scores,\n    frame_gt=gt if not SMOKE_ONLY else np.empty(0, dtype=np.uint8),\n)\n(output_dir / "run.json").write_text(json.dumps(metadata, indent=2), encoding="utf-8")\nstage_directory.cleanup()\nprint("Đầu ra", output_dir)\n'
XD_RUNNER = '\nCOMMIT = "c41067f07d252efcda18008bea367886070c33b0"\nUPSTREAM_URL = "https://github.com/nwpu-zxr/VadCLIP.git"\nVIDEO_COUNT = 800\nFRAMES_PER_FEATURE = 16\nFRAME_COUNT = 2_331_296\nFEATURE_DIM = 512\nPAPER_AP = 0.8451\nPACK_MANIFEST_NAME = "xd_test_manifest.json"\nPACK_ARCHIVE_NAME = "vadclip_xd_test800.zip"\nPREVIOUS_PACK_ARCHIVE_NAME = "vadclip_xd_test800_kaggle_v2.zip"\nPACK_MANIFEST_SHA256 = "8e5d329708857338fa94fb63a1d5733d9d8536250e6c09c3ba012f54dce997b2"\nCLIP_SHA256 = "5806e77cd80f8b59890b7e101eabd078d9fb84e6937f9e85e4ecb61988df416f"\n\nimport csv\nimport hashlib\nimport importlib.util\nimport json\nimport os\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nfrom collections import defaultdict\nfrom contextlib import ExitStack\nfrom pathlib import PurePosixPath\nfrom zipfile import BadZipFile, ZipFile\n\nif RUN_MODE not in {"smoke", "full"}:\n    raise ValueError("Evaluator XD cần chế độ smoke hoặc full.")\nif not INPUT.is_dir():\n    raise FileNotFoundError("Gắn dữ liệu qua Add Input trong Kaggle trước khi chạy.")\n\nOUTPUT.mkdir(parents=True, exist_ok=True)\nscratch = SRC_REPO.parent\nscratch.mkdir(parents=True, exist_ok=True)\nsrc_repo = SRC_REPO\nif not src_repo.exists():\n    with tempfile.TemporaryDirectory(dir=scratch) as checkout_dir:\n        checkout = Path(checkout_dir) / "source"\n        subprocess.run(["git", "clone", UPSTREAM_URL, str(checkout)], check=True)\n        subprocess.run(["git", "-C", str(checkout), "checkout", "--detach", COMMIT], check=True)\n        checkout.rename(src_repo)\n\ndef git(*args):\n    return subprocess.check_output(["git", "-C", str(src_repo), *args], text=True).strip()\n\nif git("rev-parse", "HEAD") != COMMIT or git("status", "--porcelain", "--untracked-files=all"):\n    raise RuntimeError(f"Cần checkout sạch tại commit {COMMIT}. Kiểm tra {src_repo}.")\n\nnp = importlib.import_module("numpy")\n\ndef sha256(path):\n    with path.open("rb") as stream:\n        return hashlib.file_digest(stream, "sha256").hexdigest()\n\n\ndef zip_members(path):\n    try:\n        with ZipFile(path) as archive:\n            return [name for name in archive.namelist() if not name.endswith("/")]\n    except BadZipFile as exc:\n        raise ValueError(f"ZIP chưa tải đủ hoặc bị hỏng: {path.name}") from exc\n\n\ndef basename(value):\n    return PurePosixPath(str(value).replace(chr(92), "/")).name\n\n\ndef read_split(path):\n    with path.open(newline="", encoding="utf-8-sig") as stream:\n        reader = csv.DictReader(stream)\n        if reader.fieldnames is None or not {"path", "label"} <= set(reader.fieldnames):\n            raise ValueError("CSV tác giả cần cột path và label.")\n        fields, rows = reader.fieldnames, list(reader)\n    source_paths = [row["path"] for row in rows]\n    if (\n        len(rows) != VIDEO_COUNT\n        or len(set(source_paths)) != VIDEO_COUNT\n        or any(not path or not basename(path).endswith("__0.npy") for path in source_paths)\n        or any(not row["label"] for row in rows)\n    ):\n        raise ValueError(f"Split XD phải gồm {VIDEO_COUNT} dòng feature hợp lệ, duy nhất.")\n    return fields, rows\n\n\ndef matching_files(root, expected):\n    found = defaultdict(list)\n    if FEATURE_ZIP is None:\n        if not root.is_dir():\n            raise FileNotFoundError(f"DATA_ROOT không tồn tại: {root}")\n        for path in root.rglob("*.npy"):\n            if path.name in expected:\n                found[path.name].append((path, None))\n        if found:\n            return found\n        archives = sorted(root.rglob("*.zip"))\n    else:\n        archives = [Path(FEATURE_ZIP)]\n\n    for archive_path in archives:\n        if not archive_path.is_file():\n            raise FileNotFoundError(f"Không thấy FEATURE_ZIP: {archive_path}")\n        for member in zip_members(archive_path):\n            name = basename(member)\n            if name in expected:\n                found[name].append((archive_path, member))\n    return found\n\n\ndef match_one(original, candidates):\n    # Nếu hai file cùng tên, chỉ phân giải khi hậu tố thư mục chính thức khớp duy nhất.\n    if len(candidates) <= 1:\n        return candidates\n    official = PurePosixPath(original.replace(chr(92), "/")).parts\n    for depth in range(2, len(official) + 1):\n        matches = [\n            (path, member)\n            for path, member in candidates\n            if PurePosixPath((member or path.as_posix()).replace(chr(92), "/")).parts[-depth:]\n            == official[-depth:]\n        ]\n        if len(matches) == 1:\n            return matches\n        if not matches:\n            break\n    return candidates\n\n\ndef pick_checkpoint(root):\n    if CHECKPOINT is not None:\n        path = Path(CHECKPOINT)\n        if not path.is_file() or path.suffix.lower() not in {".pth", ".zip"}:\n            raise FileNotFoundError(f"CHECKPOINT cần đường dẫn .pth hoặc .zip hợp lệ: {path}")\n        return path\n    weights = [path for path in root.rglob("*.pth") if path.name in {"model_xd.pth", "model.pth"}]\n    if len(weights) == 1:\n        return weights[0]\n    if not weights:\n        archives = [\n            path for path in root.rglob("*.zip")\n            if any(\n                basename(member) in {"model_xd.pth", "model.pth"}\n                for member in zip_members(path)\n            )\n        ]\n        if len(archives) == 1:\n            return archives[0]\n    raise RuntimeError(\n        "Gắn checkpoint VadCLIP XD-Violence. Nếu tên khác hoặc có nhiều bản, "\n        "đặt CHECKPOINT bằng đường dẫn file .pth hoặc ZIP chỉ chứa một .pth."\n    )\n\n\ndef stage_member(archive, member, target):\n    # Chỉ ghi tới tên đích do notebook tạo. Không giải nén theo đường dẫn trong ZIP.\n    target.parent.mkdir(parents=True, exist_ok=True)\n    with archive.open(member) as src, target.open("wb") as dest:\n        shutil.copyfileobj(src, dest, length=1024 * 1024)\n    return target\n\n\ndef checkpoint_from_input(root, staging):\n    path = pick_checkpoint(root)\n    if path.suffix.lower() == ".zip":\n        members = [name for name in zip_members(path) if name.lower().endswith(".pth")]\n        if len(members) != 1:\n            raise ValueError(f"ZIP checkpoint phải chứa đúng một .pth: {path.name}")\n        if basename(members[0]) == "model_ucf.pth":\n            raise ValueError("ZIP đang chứa checkpoint UCF-Crime.")\n        with ZipFile(path) as archive:\n            path = stage_member(archive, members[0], staging / "checkpoint.pth")\n    if path.name == "model_ucf.pth" or path.stat().st_size == 0:\n        raise ValueError(f"File checkpoint không hợp lệ cho XD: {path.name}")\n    with path.open("rb") as stream:\n        if stream.read(4) == b"PK\\x03\\x04":\n            zip_members(path)  # xác nhận có thư mục ZIP ở cuối file PyTorch\n    return path\n\n\ndef feature_info(path):\n    array = np.load(path, mmap_mode="r", allow_pickle=False)\n    if (\n        array.ndim != 2 or array.shape[0] == 0 or array.shape[1] != FEATURE_DIM\n        or array.dtype not in (np.float16, np.float32, np.float64)\n        or not np.isfinite(array).all()\n    ):\n        raise ValueError(f"Feature cần mảng số thực hữu hạn [T, {FEATURE_DIM}]: {path.name}")\n    return len(array), sha256(path)\n\n\ndef read_pack_manifest(root):\n    candidates = [path.read_bytes() for path in root.rglob(PACK_MANIFEST_NAME)]\n    archives = set(root.rglob(PACK_ARCHIVE_NAME)) | set(root.rglob(PREVIOUS_PACK_ARCHIVE_NAME))\n    if FEATURE_ZIP is not None:\n        archives.add(Path(FEATURE_ZIP))\n    for archive_path in sorted(archives):\n        with ZipFile(archive_path) as archive:\n            members = [\n                name for name in archive.namelist() if basename(name) == PACK_MANIFEST_NAME\n            ]\n            candidates.extend(archive.read(name) for name in members)\n    if not candidates:\n        raise FileNotFoundError(\n            "Chưa thấy manifest. Gắn Dataset VadCLIP XD-Violence Test 800 "\n            f"từ {PACK_ARCHIVE_NAME} và giữ nguyên tên file ZIP."\n        )\n    if any(hashlib.sha256(raw).hexdigest() != PACK_MANIFEST_SHA256 for raw in candidates):\n        raise ValueError("Manifest trên Kaggle không khớp bản đã khóa trong notebook.")\n\n    manifest = json.loads(candidates[0])\n    if manifest["upstream_commit"] != COMMIT:\n        raise ValueError("Commit trong manifest không đúng.")\n    return manifest\n\n\ndef check_pack_manifest(manifest, inventory, checkpoint_hash):\n    if manifest["checkpoint_sha256"] != checkpoint_hash:\n        raise ValueError("Sai checkpoint so với manifest đã khóa.")\n    actual_features = {\n        basename(row["official_path"]): {"steps": row["steps"], "sha256": row["feature_sha256"]}\n        for row in inventory\n    }\n    if actual_features != manifest["features"]:\n        names = actual_features.keys() | manifest["features"].keys()\n        first_difference = next(\n            name for name in sorted(names)\n            if actual_features.get(name) != manifest["features"].get(name)\n        )\n        raise ValueError(f"Feature trên Kaggle lệch bản đã khóa: {first_difference}")\n    return manifest["source_features_sha256"]\n\n\ndef prepare_inputs(split, gt_path, data_root, staging, upload_names=None):\n    fields, rows = read_split(split)\n    original_names = {basename(row["path"]) for row in rows}\n    if upload_names is not None and (\n        len(original_names) != VIDEO_COUNT\n        or upload_names.keys() != original_names\n        or len(set(upload_names.values())) != VIDEO_COUNT\n    ):\n        raise ValueError("Ánh xạ tên file không khớp danh sách video trong CSV gốc.")\n    names = upload_names if upload_names is not None else {name: name for name in original_names}\n    found = matching_files(data_root, set(names.values()))\n    resolved = []\n    issues = {"missing": [], "ambiguous": []}\n    for row in rows:\n        original = row["path"]\n        candidates = match_one(original, found[names[basename(original)]])\n        if len(candidates) == 0:\n            issues["missing"].append(original)\n        elif len(candidates) > 1:\n            issues["ambiguous"].append({\n                "expected": original,\n                "candidates": [str(path) if member is None else f"{path.name}::{member}"\n                               for path, member in candidates],\n            })\n        else:\n            resolved.append(candidates[0])\n    if any(issues.values()) or len(set(resolved)) != VIDEO_COUNT:\n        report = OUTPUT / "input_issues.json"\n        report.write_text(json.dumps(issues, ensure_ascii=False, indent=2), encoding="utf-8")\n        raise RuntimeError(\n            f"Thiếu {len(issues[\'missing\'])} file, trùng {len(issues[\'ambiguous\'])} dòng "\n            f"hoặc dùng lại cùng feature. Xem {report}. Kiểm DATA_ROOT/FEATURE_ZIP."\n        )\n\n    gt = np.load(gt_path, allow_pickle=False)\n    if gt.shape != (FRAME_COUNT,) or not np.array_equal(np.unique(gt), [0, 1]):\n        raise ValueError("Ground truth XD sai shape hoặc không phải vector nhị phân.")\n\n    inventory = []\n    with ExitStack() as stack:\n        archives = {}\n        for index, (row, (path, member)) in enumerate(zip(rows, resolved, strict=True)):\n            if member is not None:\n                if path not in archives:\n                    archives[path] = stack.enter_context(ZipFile(path))\n                target = staging / f"{index:04d}" / basename(member)\n                path = stage_member(archives[path], member, target)\n            count, digest = feature_info(path)\n            inventory.append({\n                "official_path": row["path"], "label": row["label"],\n                "steps": count, "feature_sha256": digest,\n            })\n            row["path"] = str(path)\n    steps = sum(item["steps"] for item in inventory)\n    if steps * FRAMES_PER_FEATURE != len(gt):\n        raise ValueError(\n            f"Feature có {steps:,} bước, cần {len(gt) // FRAMES_PER_FEATURE:,} "\n            f"theo ground truth tác giả. Kiểm phiên bản gói feature và crop."\n        )\n\n    offset = 0\n    for item in inventory:\n        stop = offset + item["steps"] * FRAMES_PER_FEATURE\n        positive_frames = int(np.count_nonzero(gt[offset:stop]))\n        if "_label_A" in basename(item["official_path"]) and positive_frames:\n            raise ValueError(f"Lệch ground truth trong video Normal: {item[\'official_path\']}")\n        item["positive_frames"] = positive_frames\n        offset = stop\n\n    resolved_csv = staging / "xd_CLIP_rgbtest_kaggle.csv"\n    with resolved_csv.open("w", newline="", encoding="utf-8") as stream:\n        writer = csv.DictWriter(stream, fieldnames=fields)\n        writer.writeheader()\n        writer.writerows(rows)\n    return resolved_csv, inventory, gt\n\n# Preflight CPU. Mỗi lần chạy tạo thư mục mới, không ghi đè input đã gắn.\nstage_directory = tempfile.TemporaryDirectory(prefix="run_", dir=scratch)\nstaging = Path(stage_directory.name)\nsplit = src_repo / "list" / "xd_CLIP_rgbtest.csv"\ngt_path = src_repo / "list" / "gt.npy"\ndata_root = Path(DATA_ROOT) if DATA_ROOT is not None else INPUT\ntry:\n    pack_manifest = read_pack_manifest(INPUT) if REQUIRE_PACK_MANIFEST else None\n    upload_names = pack_manifest["upload_names"] if pack_manifest is not None else None\n    resolved_csv, inventory, gt = prepare_inputs(split, gt_path, data_root, staging, upload_names)\n    checkpoint_path = checkpoint_from_input(INPUT, staging)\n    checkpoint_hash = sha256(checkpoint_path)\n    source_features_hash = None\n    if pack_manifest is not None:\n        source_features_hash = check_pack_manifest(pack_manifest, inventory, checkpoint_hash)\nexcept Exception:\n    stage_directory.cleanup()\n    raise\n\nreceipt = {\n    "upstream_commit": COMMIT,\n    "split_sha256": sha256(split),\n    "ground_truth_sha256": sha256(gt_path),\n    "checkpoint_sha256": checkpoint_hash,\n    "pack_manifest_sha256": PACK_MANIFEST_SHA256 if REQUIRE_PACK_MANIFEST else None,\n    "source_features_archive_sha256": source_features_hash,\n    "video_count": len(inventory),\n    "snippet_count": sum(row["steps"] for row in inventory),\n    "frame_count": len(gt),\n    "frames_per_feature": FRAMES_PER_FEATURE,\n    "videos": inventory,\n}\nif REFERENCE_MANIFEST is not None:\n    try:\n        reference = json.loads(Path(REFERENCE_MANIFEST).read_text(encoding="utf-8"))\n        for key in ("upstream_commit", "split_sha256", "ground_truth_sha256",\n                    "checkpoint_sha256", "videos"):\n            if receipt[key] != reference.get(key):\n                raise ValueError(f"Bản Kaggle lệch bản tham chiếu ở trường {key}.")\n    except Exception:\n        stage_directory.cleanup()\n        raise\nreceipt["matched_reference_manifest"] = REFERENCE_MANIFEST is not None\n\n(OUTPUT / "preflight.json").write_text(\n    json.dumps(receipt, ensure_ascii=False, indent=2), encoding="utf-8"\n)\nprint(\n    f"Preflight đạt: {len(inventory)} video, {receipt[\'snippet_count\']:,} bước, "\n    f"{len(gt):,} frame."\n)\nprint(f"Checkpoint {checkpoint_path.name}, SHA-256 {checkpoint_hash}")\nif REQUIRE_PACK_MANIFEST:\n    print("SHA-256: khớp cả 800 feature và checkpoint công bố với hai gói đã chuẩn bị.")\n\nreceipt["evaluated_checkpoint_sha256"] = checkpoint_hash\n\nimport contextlib\nimport runpy\nimport time\nimport traceback\nfrom unittest.mock import patch\n\n\n\n\ndef run_upstream():\n    full_run = RUN_MODE == "full"\n    packages = {\n        "ftfy": "ftfy", "packaging": "packaging", "regex": "regex", "tqdm": "tqdm",\n        "sklearn": "scikit-learn", "scipy": "scipy", "pandas": "pandas",\n    }\n    missing = [\n        package for module, package in packages.items()\n        if importlib.util.find_spec(module) is None\n    ]\n    if missing:\n        subprocess.run([sys.executable, "-m", "pip", "install", *missing], check=True)\n\n    import torch\n    from sklearn import metrics\n\n    if not torch.cuda.is_available():\n        raise RuntimeError("Bật Accelerator GPU T4 trong Kaggle để chạy inference.")\n    torch.cuda.set_device(0)\n    torch.manual_seed(234)\n    runtime = staging / "runtime"\n    shutil.copytree(src_repo / "src", runtime)\n    from v7_windows import overlap_forward\n\n    clip_source = runtime / "clip" / "clip.py"\n    text = clip_source.read_text(encoding="utf-8")\n    old_import = "from pkg_resources import packaging"\n    if text.count(old_import) != 1:\n        raise RuntimeError("Không tìm thấy import CLIP cần sửa tương thích tại commit đã khóa.")\n    clip_source.write_text(text.replace(old_import, "import packaging.version"), encoding="utf-8")\n\n    if CLIP_WEIGHTS is not None:\n        source = Path(CLIP_WEIGHTS)\n        if not source.is_file() or sha256(source) != CLIP_SHA256:\n            raise ValueError("CLIP_WEIGHTS cần file OpenAI ViT-B-16.pt đúng SHA-256.")\n        cache = Path.home() / ".cache" / "clip"\n        cache.mkdir(parents=True, exist_ok=True)\n        target = cache / "ViT-B-16.pt"\n        if source.resolve() != target.resolve():\n            with tempfile.TemporaryDirectory(dir=cache) as copy_dir:\n                temporary = Path(copy_dir) / target.name\n                shutil.copyfile(source, temporary)\n                if sha256(temporary) != CLIP_SHA256:\n                    raise ValueError("Bản sao trọng số CLIP không khớp SHA-256.")\n                temporary.replace(target)\n\n    output_root = OUTPUT / RUN_MODE\n    output_root.mkdir(exist_ok=True)\n    output_dir = Path(tempfile.mkdtemp(prefix="run_", dir=output_root))\n    print(f"Đang chạy evaluator gốc. Log: {output_dir / \'upstream.log\'}", flush=True)\n    native_ap = metrics.average_precision_score\n    ap_calls = []\n    upstream_completed = False\n    post_ap_error = None\n    checkpoint_loaded = False\n    forwards = 0\n    torch_load = torch.load\n\n    class SmokeComplete(Exception):\n        pass\n\n    def load_checkpoint(file, *args, **kwargs):\n        nonlocal checkpoint_loaded\n        if not isinstance(file, (str, os.PathLike)) or Path(file).resolve() != checkpoint_path.resolve():\n            return torch_load(file, *args, **kwargs)\n        checkpoint_loaded = True\n        state = torch_load(file, map_location="cpu", weights_only=True)\n        for field in ("state_dict", "model_state_dict"):\n            if isinstance(state, dict) and field in state:\n                return state[field]\n        return state\n\n    def record_ap(y_true, y_score, *args, **kwargs):\n        value = native_ap(y_true, y_score, *args, **kwargs)\n        if np.asarray(y_true).shape == gt.shape and np.array_equal(y_true, gt):\n            scores = np.asarray(y_score).reshape(-1)\n            if scores.shape != gt.shape or not np.isfinite(scores).all():\n                raise ValueError("Điểm frame từ evaluator XD sai shape hoặc chứa NaN/Inf.")\n            grouped = scores.reshape(-1, FRAMES_PER_FEATURE)\n            if not np.all(grouped == grouped[:, :1]):\n                raise ValueError("Điểm từ evaluator không theo quy tắc lặp 16 frame.")\n            ap_calls.append((float(value), grouped[:, 0].copy()))\n        return value\n\n    original_cwd = Path.cwd()\n    original_path = sys.path.copy()\n    original_argv = sys.argv.copy()\n    original_bytecode = sys.dont_write_bytecode\n    try:\n        os.chdir(runtime)\n        sys.path.insert(0, str(runtime))\n        sys.dont_write_bytecode = True\n        from model import CLIPVAD\n        from utils.tools import get_batch_mask\n        from xd_option import parser\n\n        # Giữ các giá trị mặc định XD của tác giả, chỉ thay đường dẫn input.\n        destinations = {action.dest for action in parser._actions}\n        overrides = {\n            "test_list": str(resolved_csv),\n            "gt_path": str(gt_path),\n            "model_path": str(checkpoint_path),\n        }\n        defaults = parser.parse_args([])\n        for key in ("gt_segment_path", "gt_label_path"):\n            default = Path(getattr(defaults, key))\n            path = (src_repo / "src" / default).resolve()\n            if not path.is_file():\n                path = (src_repo / default).resolve()\n            relative = path.relative_to(src_repo)\n            git("ls-files", "--error-unmatch", relative.as_posix())\n            overrides[key] = str(path)\n        if not overrides.keys() <= destinations:\n            raise RuntimeError(f"CLI upstream thiếu tham số: {overrides.keys() - destinations}")\n        flags = []\n        for action in parser._actions:\n            if action.dest in overrides:\n                flags.extend((action.option_strings[0], overrides[action.dest]))\n\n        from latency_inference import InferenceLatency\n\n        latency = InferenceLatency(LATENCY_WARMUP, LATENCY_REPEATS)\n        from v21_diagnostics import EvaluationTrace\n        flow_trace = EvaluationTrace(output_dir / "diagnostics", "xd", VARIANT)\n        with resolved_csv.open(newline="", encoding="utf-8-sig") as feature_stream:\n            feature_paths = [Path(item["path"]) for item in csv.DictReader(feature_stream)]\n        if len(feature_paths) != len(inventory):\n            raise ValueError("XD resolved feature paths do not match evaluator inventory")\n        from benchmark_reporting import count_parameters\n\n        parameter_counts = {}\n        from v21_model import load_full_model\n        from v21_native import load_native_model\n\n        full_model, full_provenance = None, None\n        original_forward = CLIPVAD.forward\n\n        smoke_forwards = max(3, next(\n            i for i, row in enumerate(inventory, 1) if row["steps"] > defaults.visual_length\n        ))\n\n        def count_forward(self, images, padding_mask, text, lengths):\n            nonlocal forwards, full_model, full_provenance\n            if forwards == 0:\n                if V21_SPACE == "native_cosine":\n                    full_model, full_provenance = load_native_model(\n                        self, V21_MODEL_PATH, V21_MODEL_SHA256, checkpoint_hash,\n                        images.device, native_forward=original_forward)\n                elif V21_SPACE is not None:\n                    full_model, full_provenance = load_full_model(\n                        self, V21_SPACE, GEOMETRY_CONFIG, V21_MODEL_PATH, V21_MODEL_SHA256,\n                        checkpoint_hash, images.device)\n                parameter_counts.update(count_parameters(\n                    self, (full_model.geometry,) if hasattr(full_model, "geometry") else None))\n\n            def forward(x, mask, prompts, sizes):\n                if full_model is not None:\n                    return full_model(x, mask, prompts, sizes)\n                return original_forward(self, x, mask, prompts, sizes)\n\n            def dispatch():\n                if VARIANT == "v7":\n                    result = overlap_forward(forward, images, padding_mask, text, lengths, get_batch_mask)\n                else:\n                    result = forward(images, padding_mask, text, lengths)\n                return result\n\n            row = inventory[forwards]\n            result = latency.measure(\n                dispatch, images.device, row["official_path"], row["steps"],\n                images.shape, images.dtype,\n            )\n            flow_trace.observe(row["official_path"], self, dispatch, images, lengths,\n                               padding_mask, result, row["steps"], getattr(full_model, "geometry", None), text,\n                               expected_features=np.load(feature_paths[forwards], allow_pickle=False))\n            forwards += 1\n            if RUN_MODE == "smoke" and forwards == smoke_forwards:\n                if any(not torch.isfinite(tensor).all() for tensor in result):\n                    raise ValueError("Smoke test sinh NaN/Inf.")\n                raise SmokeComplete\n            return result\n\n        sys.argv = [str(runtime / "xd_test.py"), *flags]\n        torch.cuda.reset_peak_memory_stats()\n        started = time.perf_counter()\n        with (\n            (output_dir / "upstream.log").open("w", encoding="utf-8") as log,\n            contextlib.redirect_stdout(log),\n            contextlib.redirect_stderr(log),\n            patch.object(torch, "load", load_checkpoint),\n            patch.object(metrics, "average_precision_score", record_ap),\n            patch.object(CLIPVAD, "forward", count_forward),\n        ):\n            try:\n                runpy.run_path(str(runtime / "xd_test.py"), run_name="__main__")\n                upstream_completed = True\n            except SmokeComplete:\n                if RUN_MODE != "smoke":\n                    raise\n            except Exception as exc:\n                if not full_run or len(ap_calls) != 2:\n                    raise\n                traceback.print_exc(file=log)\n                post_ap_error = f"{type(exc).__name__}: {exc}"\n        elapsed = time.perf_counter() - started\n    finally:\n        os.chdir(original_cwd)\n        sys.argv = original_argv\n        sys.path[:] = original_path\n        sys.dont_write_bytecode = original_bytecode\n\n    if not checkpoint_loaded or forwards == 0:\n        raise RuntimeError("Chưa xác nhận upstream đã nạp checkpoint XD và chạy forward.")\n\n    flow_trace.finish()\n    latency_summary = latency.save(\n        output_dir, "xd", VARIANT, RUN_MODE, torch.device("cuda:0"),\n    )\n    result = {\n        "parameters": parameter_counts,\n        "latency": latency_summary,\n        **receipt,\n        "geometry": full_model.geometry.receipt() if hasattr(full_model, "geometry") else None,\n        "model_control": full_model.model_receipt() if V21_SPACE == "native_cosine" else None,\n        "full_model_provenance": full_provenance,\n        "initial_v0_checkpoint_sha256": checkpoint_hash,\n        "evaluated_checkpoint_sha256": V21_MODEL_SHA256 if full_model else checkpoint_hash,\n        "run_kind": "smoke_inference" if RUN_MODE == "smoke" else "full_checkpoint_inference",\n        "runtime_patch": "CLIP imports packaging.version directly",\n        "clip_backbone_sha256": CLIP_SHA256,\n        "forward_calls": forwards,\n        "visual_block_length": defaults.visual_length,\n        "upstream_completed": upstream_completed,\n        "post_ap_error": post_ap_error,\n        "gpu": torch.cuda.get_device_name(0),\n        "torch": torch.__version__,\n        "elapsed_seconds": elapsed,\n        "peak_torch_vram_mib": torch.cuda.max_memory_allocated() / 2**20,\n        "metrics": None,\n    }\n    if full_run:\n        if len(ap_calls) != 2:\n            raise RuntimeError(\n                f"Cần hai AP cấp frame từ xd_test.py, nhận {len(ap_calls)}. "\n                f"Xem {output_dir / \'upstream.log\'}."\n            )\n        scores = np.column_stack([column for _, column in ap_calls])\n        result["paper_table_1_frame_ap"] = PAPER_AP\n        result["metrics"] = {\n            f"branch_{index + 1}": {\n                "frame_ap": ap,\n                "roc_auc": float(metrics.roc_auc_score(gt, np.repeat(column, FRAMES_PER_FEATURE))),\n                "gap_vs_paper_percentage_points": 100 * (ap - PAPER_AP),\n            }\n            for index, (ap, column) in enumerate(ap_calls)\n        }\n        score_columns = ["branch_1", "branch_2"]\n        steps_per_video = [item["steps"] for item in inventory]\n        result["score_columns"] = score_columns\n        np.savez_compressed(\n            output_dir / "predictions.npz",\n            official_path=np.asarray([item["official_path"] for item in inventory]),\n            video_label=np.asarray([item["label"] for item in inventory]),\n            snippet_offsets=np.cumsum([0] + steps_per_video),\n            score_columns=np.asarray(score_columns),\n            scores=scores,\n            frame_gt=gt,\n        )\n    elif forwards != smoke_forwards:\n        raise RuntimeError("Smoke test chưa đủ lượt forward.")\n\n    (output_dir / "run.json").write_text(\n        json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8"\n    )\n    if full_run:\n        if post_ap_error is not None:\n            print(f"Script gốc lỗi sau khi tính đủ hai AP. Xem upstream.log: {post_ap_error}")\n        for name, values in result["metrics"].items():\n            if name == "branch_2":\n                print(\n                    f"{name} [XD primary / alignment]: AP {values[\'frame_ap\'] * 100:.4f}% "\n                    f"(vs paper 84.51%: {values[\'gap_vs_paper_percentage_points\']:+.4f} pp; "\n                    "not a delta vs a previous V0 run)"\n                )\n            else:\n                print(f"{name} [auxiliary / classification]: AP {values[\'frame_ap\'] * 100:.4f}%")\n    else:\n        print("Smoke đạt, gồm video dài hơn block.")\n    print(f"Đầu ra: {output_dir}")\n\n\ntry:\n    if RUN_MODE == "preflight":\n        print("Đã kiểm input. Chọn GPU và RUN_MODE = \'smoke\' để thử checkpoint.")\n    else:\n        run_upstream()\nfinally:\n    stage_directory.cleanup()\n'

exec(SOURCES["orchestrator_v21.py"], globals())

from IPython.display import FileLink, display  # noqa: E402

result_zip = globals().get("RESULT_ZIP", globals().get("LAST_RESULT_ZIP"))
if result_zip is None:
    raise RuntimeError("No result ZIP yet. Check the run cell error and output directory.")
source_zip = Path(result_zip).resolve()
if not source_zip.is_file():
    raise FileNotFoundError(source_zip)
download_zip = Path.cwd() / f"v21_{source_zip.parent.name}_results.zip"
if source_zip != download_zip.resolve():
    shutil.copy2(source_zip, download_zip)
display(FileLink(download_zip.name))
print("If the link fails, use Kaggle Output/Files:", download_zip)
